    "Các nhóm sản phẩm xuất khẩu bao gồm sản phẩm làm từ gỗ tự nhiên, MDF, plywood và các vật liệu phục vụ sản xuất nội thất.": "Export product groups include products made from natural wood, MDF, plywood and materials for furniture production.",
