    "Các vấn đề phát sinh trong sản xuất, kiểm hàng hoặc xuất hàng được ghi nhận, báo cáo và trao đổi rõ ràng để có phương án xử lý kịp thời.": "Problems arising in production, goods inspection or shipment are recorded, reported and clearly discussed for timely resolution.",
