    "Doanh nghiệp muốn tài trợ chương trình giáo dục": "Businesses want to sponsor educational programs",
    "Dù sản xuất tại bất kỳ nhà máy nào, mọi hoạt động đều phải tuân theo:": "Regardless of production at any factory, all activities must comply with:",
    "Duy trì chất lượng ổn định trên toàn hệ thống": "Maintain stable quality throughout the system",
    "Duy trì kênh phản hồi trực tiếp từ cộng đồng thụ hưởng": "Maintain a direct feedback channel from the beneficiary community",
    "DỮ LIỆU": "DATA",
    "Dữ liệu bao gồm:": "Data includes:",
    "Dữ liệu được cập nhật theo thời gian thực, kiểm soát trước khi chia sẻ và phân quyền theo từng tài khoản.": "Data is updated in real time, controlled before sharing and authorized by each account.",
    "Dữ liệu được luân chuyển theo nguyên tắc:": "Data is circulated according to the principle:",
    "Dữ liệu không chỉ để lưu trữ, mà để:": "Data is not just for storage, but for:",
    "Dữ liệu lỗi": "Error data",
    "Dữ liệu QC": "QC data",
    "Dữ liệu QC được ghi nhận trực tiếp tại hiện trường, lưu trữ trên hệ thống và kiểm soát nhiều lớp trước khi sử dụng.": "QC data is recorded directly at the scene, stored on the system and controlled in many layers before use.",
    "Dữ liệu sản xuất": "Production data",
    "Dữ liệu sản xuất được quản lý tập trung": "Production data is centrally managed",
    "Dữ liệu tiến độ": "Progress data",
    "Đa thị trường": "Multi-market",
    "Đảm bảo chất lượng và tiến độ ở quy mô lớn": "Ensuring quality and progress on a large scale",
    "Đảm bảo dữ liệu cung cấp cho sale và khách hàng là dữ liệu đã được kiểm soát": "Ensure data provided to sales and customers is controlled data",
    "Đảm bảo quyền lợi của các bên tham gia": "Ensure the rights of participating parties",
    "Đảm bảo sản phẩm đạt yêu cầu trước khi xuất hàng": "Ensure products meet requirements before shipping",
    "Đánh giá đầu ra theo chỉ số đã cam kết": "Evaluate output according to committed indicators",
    "Đánh giá năng lực theo tiêu chí thống nhất": "Evaluate capacity according to unified criteria",
    "Đánh giá tác động sau chương trình": "Evaluate the impact after the program",
    "Đánh giá theo bộ tiêu chí đã công bố": "Evaluated according to the published criteria set",
    "Đào tạo kỹ năng mềm và tác phong nghề nghiệp": "Soft skills and professional behavior training",
    "Đào tạo kỹ năng nghề và an toàn làm việc": "Vocational skills and work safety training",
    "Đào tạo kỹ năng nghề, phát triển đội ngũ quản lý và nâng cao năng lực sản xuất.": "Vocational skills training, management team development and production capacity improvement.",
    "Đào tạo kỹ năng số và quản trị dữ liệu cơ bản": "Training on basic digital skills and data management",
    "Đào tạo thực tế trong sản xuất": "Practical training in production",
    "Đầu tư cho con người là nền tảng của phát triển dài hạn.": "Investing in people is the foundation of long-term development.",
    "Đầu tư con người": "Investing in people",
    "Đầu tư vào con người để tạo năng lực vận hành bền vững cho cộng đồng và doanh nghiệp.": "Invest in people to create sustainable operating capacity for communities and businesses.",
    "Đầu tư vào đào tạo, môi trường làm việc và cơ hội phát triển cho đội ngũ nhân sự.": "Invest in training, working environment and development opportunities for staff.",
    "Đây là bước phát triển quan trọng trong việc tách hoạt động kiểm soát chất lượng khỏi bộ máy sản xuất, giúp ANSLIFE nâng cao tính khách quan, khả năng truy xuất và mức độ kiểm soát trong các đơn hàng xuất khẩu.": "This is an important development in separating quality control activities from the production apparatus, helping ANSLIFE improve objectivity, traceability and level of control in export orders.",
    "Đây là giai đoạn ANSLIFE mở rộng từ sản xuất nội thất sang thiết kế, tư vấn và triển khai không gian nội thất hoàn chỉnh.": "This is the period when ANSLIFE expanded from furniture production to design, consulting and implementation of complete interior spaces.",
    "Đây là lõi vận hành của hệ thống ANSLIFE.": "This is the operating core of the ANSLIFE system.",
    "Đây là lý do ANSLIFE chuẩn hóa việc kiểm soát vật liệu, chuẩn bị hàng trắng, kiểm tra mộng liên kết, kiểm soát hoàn thiện sơn, bảo vệ đóng gói, bảng tiến độ dự án và hồ sơ lỗi xuyên đơn hàng.": "This is why ANSLIFE standardizes material control, white goods preparation, joint inspection, paint finish control, packaging protection, project schedule sheets and cross-order defect records.",
    "Đây là lý do ANSLIFE tiếp tục đầu tư vào kiểm soát vật liệu, kế hoạch sản xuất, kiểm tra chất lượng, tiêu chuẩn đóng gói, theo dõi dự án và hồ sơ cải tiến.": "This is why ANSLIFE continues to invest in material control, production planning, quality inspection, packaging standards, project tracking and improvement records.",
    "Đây là một cột mốc quan trọng, vì thị trường Nhật Bản có yêu cầu cao về chất lượng, độ ổn định, tiêu chuẩn đóng gói, kiểm soát chi tiết và khả năng duy trì tiêu chuẩn sản phẩm trong dài hạn.": "This is an important milestone, as the Japanese market has high requirements for quality, stability, packaging standards, detailed control and the ability to maintain product standards over the long term.",
    "Đây là nền tảng quan trọng để ANSLIFE phát triển hệ thống": "This is an important foundation for ANSLIFE to develop the system",
    "Đây là trung tâm kiểm soát toàn bộ hoạt động của ANSLIFE.": "This is the center that controls all ANSLIFE operations.",
    "Đề xuất điều chỉnh về kết cấu, vật liệu, màu sơn và khả năng sản xuất": "Propose adjustments to structure, materials, paint colors and manufacturing capabilities",
    "Đến giai đoạn này, ANSLIFE sở hữu năng lực sản xuất thông qua hệ thống nhà máy vệ tinh đa dạng, mạng lưới cung cấp nguyên liệu và kinh nghiệm vận hành các đơn hàng xuất khẩu.": "At this stage, ANSLIFE possesses production capacity through a diverse satellite factory system, raw material supply network and experience in operating export orders.",
