    "Đối với ANSLIFE, dữ liệu không chỉ dùng để báo cáo. Dữ liệu là công cụ làm việc để ra quyết định tốt hơn, kiểm soát chất lượng tốt hơn và quản lý dự án tốt hơn.": "For ANSLIFE, data is not just for reporting. Data is a working tool for better decision making, better quality control, and better project management.",
    "Đối với ANSLIFE, niềm tin không được tạo ra chỉ bằng lời nói. Niềm tin được tạo ra bằng hành động hằng ngày, dữ liệu rõ ràng, trách nhiệm được lặp lại và tinh thần sẵn sàng cải tiến sau mỗi dự án.": "For ANSLIFE, trust is not created just by words. Trust is created with daily action, clear data, repeatable accountability, and a willingness to improve with each project.",
    "Đối với chúng tôi, niềm tin dài hạn phải được xây dựng bằng trách nhiệm được lặp lại, dữ liệu minh bạch, cải tiến liên tục và những hành động thực tế trong vận hành hằng ngày.": "For us, long-term trust must be built with repeat accountability, transparent data, continuous improvement and real actions in daily operations.",
