    "được hình thành từ nền tảng sản xuất nội thất thực tế tại Việt Nam. Từ một xưởng sản xuất thủ công tại làng nghề Cần Kiệm, Thạch Thất, Hà Nội, ANSLIFE từng bước phát triển năng lực thiết kế, thi công, gia công xuất khẩu, kiểm soát chất lượng,": "was formed from the foundation of actual furniture production in Vietnam. From a handicraft workshop in Can Kiem craft village, Thach That, Hanoi, ANSLIFE has gradually developed the capacity of design, construction, export processing, quality control,",
