    "Giai đoạn này giúp ANSLIFE tích lũy thêm kinh nghiệm về nhu cầu người dùng, thiết kế nội thất, thi công thực tế và quản lý dự án nội thất trong nước.": "This phase helps ANSLIFE accumulate more experience in user needs, interior design, actual construction and domestic interior project management.",
    "Giai đoạn này tập trung vào các sản phẩm nội thất gia đình như tủ áo, giường, bàn, ghế và các sản phẩm gỗ phục vụ nhu cầu nhà ở.": "This phase focuses on home interior products such as wardrobes, beds, tables, chairs and wooden products to serve housing needs.",
