    "Kết nối nguyên liệu, sản xuất, QC và hậu cần để giảm rủi ro tiến độ.": "Connect materials, production, QC and logistics to reduce schedule risk.",
    "Kết nối với ANSLIFE": "Connect to ANSLIFE",
    "Kết quả chương trình được đánh giá theo chu kỳ quý và năm để liên tục nâng chất lượng hoạt động.": "Program results are evaluated on a quarterly and annual basis to continuously improve the quality of operations.",
