    "Khám phá mô hình hoạt động và năng lực của ANSLIFE.": "Explore ANSLIFE's operating model and capabilities.",
    "Khảo sát nhu cầu thực địa và xác định nhóm thụ hưởng": "Survey field needs and identify beneficiary groups",
    "Khi làm việc với một khách hàng, chúng tôi không chỉ nhìn vào đơn hàng hiện tại. Chúng tôi xem xét cách để đơn hàng tiếp theo ổn định hơn, chu kỳ sản xuất tiếp theo hiệu quả hơn và lô hàng tiếp theo đáng tin cậy hơn.": "When working with a customer, we don't just look at the current order. We look at how to make your next order more stable, your next production cycle more efficient, and your next shipment more reliable.",
    "Khi một vấn đề xảy ra, ANSLIFE không muốn chỉ đóng lại sau một lần sửa chữa. Chúng tôi muốn hiểu đó là lỗi đơn lẻ hay lỗi lặp lại, lỗi đến từ vật liệu, phương pháp sản xuất, phương pháp kiểm tra, đóng gói, logistics hay giao tiếp.": "When a problem occurs, ANSLIFE does not want to simply close down after one repair. We want to understand whether it is a single error or a repeat error, whether the error comes from materials, production methods, inspection methods, packaging, logistics or communication.",
    "Kho bãi an toàn, quản lý tồn kho và chuẩn bị xuất hàng định kỳ.": "Safe warehouse, inventory management and preparation for periodic shipment.",
    "Không chỉ trao học bổng, chúng tôi đồng hành cùng hành trình học tập.": "Not only do we award scholarships, we accompany the learning journey.",
    "Không làm theo chiến dịch ngắn hạn, mà xây chương trình có vòng đời rõ ràng.": "Don't follow short-term campaigns, but build programs with a clear life cycle.",
    "Không ngừng nâng cao chất lượng sản phẩm và dịch vụ.": "Continuously improve product and service quality.",
    "Không phụ thuộc vào một nhà máy": "Not dependent on a factory",
    "Khởi đầu từ xưởng sản xuất nội thất thủ công": "Starting from a handmade furniture factory",
    "khu vực kiểm định chất lượng độc lập": "independent quality inspection area",
    "Khu vực này được phát triển nhằm hỗ trợ kiểm tra độ bền, kết cấu, khả năng chịu lực, độ ổn định và các tiêu chuẩn cơ học khác theo yêu cầu của từng buyer và từng thị trường.": "This area was developed to support testing of durability, structure, bearing capacity, stability and other mechanical standards required by each buyer and each market.",
    "Khuyến khích nỗ lực học tập và phát triển năng lực": "Encourage learning efforts and capacity development",
