    "Mà vẫn:": "But still:",
    "Mạng lưới nhà máy & đối tác rộng khắp": "Extensive network of factories & partners",
    "Mạng lưới nhà máy do ANSLIFE điều phối đáp ứng nhiều yêu cầu và tiêu chuẩn.": "The factory network coordinated by ANSLIFE meets many requirements and standards.",
    "Mạng lưới nhà máy vệ tinh": "Satellite factory network",
    "Mạng lưới phối hợp địa phương": "Local coordination network",
    "Mẫu sản phẩm, cấu kiện, màu sắc, vật liệu và bề mặt hoàn thiện được lưu giữ làm tiêu chuẩn đối chiếu trong quá trình sản xuất và kiểm hàng.": "Product samples, components, colors, materials and surface finishes are kept as reference standards during production and inspection.",
    "MINH BẠCH": "TRANSPARENCY",
    "Minh bạch giúp giảm rủi ro và tăng độ tin cậy trong hợp tác.": "Transparency helps reduce risks and increase trust in cooperation.",
    "Minh bạch trong công việc và dữ liệu": "Transparency in work and data",
    "Mọi đóng góp đều được theo dõi và báo cáo theo từng chương trình.": "All contributions are tracked and reported by program.",
    "Mọi hoạt động đều đi qua quy trình chuẩn để bảo đảm hiệu quả nguồn lực.": "All activities go through standard procedures to ensure resource efficiency.",
    "Mọi hoạt động trong sản xuất đều được:": "All production activities are:",
    "Mọi thông tin trong hệ thống đều được ghi nhận, lưu trữ và sử dụng để phục vụ vận hành.": "All information in the system is recorded, stored and used for operations.",
    "Mô hình này cho phép ANSLIFE:": "This model allows ANSLIFE:",
    "Mô hình này cho phép mở rộng công suất linh hoạt, giảm phụ thuộc vào một đơn vị sản xuất và tối ưu chi phí, tiến độ.": "This model allows flexible capacity expansion, reduces dependence on one production unit and optimizes costs and progress.",
    "Mô hình phối hợp đào tạo": "Training coordination model",
    "Mô hình triển khai linh hoạt theo thiết kế của khách hàng hoặc đồng phát triển mẫu.": "Flexible deployment model according to customer's design or co-developed model.",
    "Mỗi cá nhân là một phần trong hệ vận hành chung.": "Each individual is part of a common operating system.",
    "Mỗi dự án cần có hồ sơ rõ ràng: việc gì đã hoàn thành, việc gì đang thực hiện, việc gì còn lại và rủi ro nào cần được theo dõi.": "Every project needs clear records: what's been done, what's in progress, what's remaining, and what risks need to be tracked.",
    "Mỗi đơn hàng có checklist kiểm tra riêng, bao gồm kích thước, kết cấu, độ hoàn thiện, màu sắc, độ ẩm, đóng gói, nhãn mác và tình trạng hàng trước khi xuất.": "Each order has its own inspection checklist, including size, texture, finish, color, moisture, packaging, label and condition before shipping.",
    "Mỗi lỗi, khiếu nại, kết quả kiểm tra và nhận xét của khách hàng đều được xem là thông tin có giá trị cho việc cải tiến.": "Every defect, complaint, test result and customer comment is considered valuable information for improvement.",
    "Mỗi lớp có vai trò rõ ràng, kết nối với nhau thông qua hệ thống dữ liệu.": "Each layer has a clear role, connected to each other through the data system.",
    "Mỗi năm ANSLIFE triển khai danh mục hoạt động theo ba nhóm tác động chính.": "Each year ANSLIFE deploys a list of activities according to three main impact groups.",
    "Mỗi nhà máy là một phần của hệ sinh thái, không hoạt động độc lập mà được kiểm soát trong cùng một hệ thống.": "Each factory is part of an ecosystem, not operating independently but controlled within the same system.",
    "Mỗi tài khoản có quyền truy cập riêng, có phạm vi dữ liệu riêng và làm việc trên cùng một hệ thống.": "Each account has its own access rights, has its own data scope and works on the same system.",
    "Môi trường": "Environment",
    "Mỗi vai trò trong hệ thống đều:": "Each role in the system is:",
    "Một cải tiến đã hoàn thành không nên biến mất sau một lô hàng. Nó cần trở thành tiêu chuẩn cho các đơn hàng tiếp theo.": "A completed improvement should not disappear after one shipment. It needs to become the standard for future orders.",
    "Một vấn đề chỉ thật sự được xử lý khi nó không còn lặp lại trong các đơn hàng sau.": "A problem can only be truly resolved when it no longer recurs in future orders.",
    "Mở rộng cơ hội nghề nghiệp dài hạn cho người lao động": "Expand long-term career opportunities for workers",
    "Mở rộng số lượng chương trình hỗ trợ": "Expand the number of supported programs",
    "Mở rộng thêm nhà máy": "Expanding the factory",
    "Mở rộng thị trường": "Expanding the market",
    "Mở rộng vai trò vận hành và quản lý dự án xuất khẩu": "Expanding export project management and operations roles",
    "Mở rộng xuất khẩu và ra mắt thương hiệu ANSLIFE": "Expanding exports and launching the ANSLIFE brand",
    "Mục tiêu của chúng tôi không chỉ là xuất hàng. Mục tiêu của chúng tôi là giúp khách hàng nhận được sản phẩm ổn định, có thể truy xuất và đáng tin cậy.": "Our goal is not just to ship goods. Our goal is to help customers receive stable, traceable and reliable products.",
    "Mục tiêu của quỹ": "Objective of the fund",
    "Mức độ tham gia của đối tác cộng đồng": "Level of community partner involvement",
    "Năng lực cốt lõi": "Core competencies",
    "Nâng cao năng lực": "Capacity building",
    "Nâng cao năng lực sản xuất và quản trị": "Improve production and management capacity",
    "Nâng cao tiêu chuẩn chung": "Raise overall standards",
    "Nâng chuẩn đánh giá hiệu quả tác động": "Raise standards for evaluating impact effectiveness",
    "Nâng kỹ năng thực hành phù hợp nhu cầu sản xuất thực tế": "Improve practical skills to suit actual production needs",
    "ngành nội thất, bao gồm các nguồn cung cấp gỗ cao su, gỗ tràm, vải không dệt và các vật liệu phục vụ sản xuất nội thất.": "furniture industry, including supplies of rubber wood, acacia wood, non-woven fabrics and materials for furniture production.",
    "Nghiệm thu kết quả và tổng hợp báo cáo tác động": "Accept results and compile impact reports",
    "Ngoài hoạt động sản xuất và cung ứng, ANSLIFE bắt đầu tham gia sâu hơn vào việc vận hành, điều phối và quản lý các dự án xuất khẩu, bao gồm theo dõi tiến độ, phối hợp nhà máy, kiểm tra chất lượng, chuẩn bị hàng hóa và hỗ trợ kế hoạch xuất hàng.": "In addition to production and supply activities, ANSLIFE began to participate more deeply in the operation, coordination and management of export projects, including progress monitoring, factory coordination, quality inspection, goods preparation and export planning support.",
    "Ngôn ngữ hỗ trợ": "Supported languages",
    "Nguồn vật liệu liên tục, đa dạng, ổn định và có kiểm soát.": "Continuous, diverse, stable and controlled source of materials.",
