    "QC độc lập": "Independent QC",
    "Kiểm định chất lượng": "Quality inspection",
    "QC độc lập & kiểm soát chất lượng": "Independent QC & quality control",
    "QC độc lập đáng tin cậy": "Reliable independent QC",
    "QC độc lập theo tiêu chuẩn quốc tế": "Independent QC according to international standards",
    "QC là lõi của hệ sinh thái ANSLIFE.": "QC is the core of the ANSLIFE ecosystem.",
    "QC upload dữ liệu trực tiếp": "QC uploads data directly",
    "Qua từng giai đoạn, ANSLIFE không chỉ phát triển như một đơn vị sản xuất nội thất, mà dần hình thành một hệ thống sản xuất, chuỗi cung ứng, kiểm soát chất lượng và xuất khẩu có thể vận hành linh hoạt tại Việt Nam.": "Through each stage, ANSLIFE not only developed as a furniture manufacturing unit, but gradually formed a production, supply chain, quality control and export system that can operate flexibly in Vietnam.",
    "Quan điểm cốt lõi của ANSLIFE về chất lượng, sự ổn định, niềm tin và hợp tác dài hạn.": "ANSLIFE's core philosophy is quality, stability, trust and long-term cooperation.",
    "Quản lý bản vẽ kỹ thuật": "Technical drawing management",
    "Quản lý khách hàng": "Customer management",
    "Quản lý vật liệu & màu sắc": "Material & color management",
    "Quy cách đóng gói, carton mark, nhãn hàng, mã sản phẩm, pallet, container loading hoặc LCL/FCL shipment được kiểm soát theo yêu cầu của từng buyer.": "Packaging specifications, carton mark, brand, product code, pallet, container loading or LCL/FCL shipment are controlled according to each buyer's requirements.",
    "Quỹ được thiết kế với mục tiêu rõ ràng, đo lường được và có tính liên tục qua từng năm.": "The Fund is designed with clear, measurable and continuous goals year after year.",
    "Quỹ được xây theo lộ trình dài hạn, gắn với chiến lược phát triển cộng đồng của ANSLIFE.": "The fund is built according to a long-term roadmap, associated with ANSLIFE's community development strategy.",
    "Quỹ học bổng": "Scholarship Fund",
    "Quỹ học bổng và cộng đồng ANSLIFE được xây dựng như một chương trình phát triển bền vững, tập trung hỗ trợ giáo dục và tạo tác động tích cực lâu dài cho địa phương.": "The ANSLIFE Scholarship and Community Fund is built as a sustainable development program, focusing on supporting education and creating a long-term positive impact for the locality.",
    "Quỹ không chỉ hỗ trợ tài chính mà còn thúc đẩy cơ hội học tập bền vững.": "The Foundation not only provides financial support but also promotes sustainable learning opportunities.",
    "Quy trình được thiết kế ngắn gọn nhưng có kiểm soát để bảo đảm tính minh bạch.": "The process is designed to be brief but controlled to ensure transparency.",
    "Quy trình làm việc": "Workflow",
    "Quy trình minh bạch": "Transparent process",
    "Quy trình tham gia": "Participation process",
    "Quy trình triển khai chương trình": "Program implementation process",
    "Quy trình vận hành": "Operating procedures",
    "Quy trình xét chọn": "Selection process",
    "Quy trình xét chọn được chuẩn hóa để bảo đảm công bằng và minh bạch.": "The selection process is standardized to ensure fairness and transparency.",
    "R&D giúp rút ngắn thời gian phát triển mẫu, tăng tính khả thi khi sản xuất và tối ưu chi phí mà vẫn giữ chất lượng.": "R&D helps shorten sample development time, increase production feasibility and optimize costs while maintaining quality.",
    "R&D không tách rời sản xuất. R&D là một phần của hệ sinh thái sản xuất.": "R&D is not separate from production. R&D is part of the manufacturing ecosystem.",
    "Ra quyết định dựa trên dữ liệu lỗi, lead time và phản hồi sau giao hàng.": "Make decisions based on defect data, lead time, and post-delivery feedback.",
    "Sale không sử dụng dữ liệu cảm tính. Mọi thông tin đều dựa trên dữ liệu đã được xác nhận.": "Sales does not use sentiment data. All information is based on confirmed data.",
    "Sale theo dõi đơn hàng": "Sales tracks orders",
