    "Sản xuất nội thất, cấu kiện, chuỗi cung ứng vật liệu, lưu kho, QC độc lập, vận hành dự án, tài trợ thương mại, đóng gói và xuất hàng": "Furniture manufacturing, components, material supply chain, warehousing, independent QC, project operations, trade finance, packaging and shipping",
