    "Số 63 KDC Hiệp Thành 1, Phường Phú Lợi, Thành Phố Hồ Chí Minh, Việt Nam": "No. 63 Hiep Thanh 1 Residential Area, Phu Loi Ward, Ho Chi Minh City, Vietnam",
