    "Sự linh hoạt được xây dựng trên nền tảng hệ thống, không phải xử lý tình huống ngẫu nhiên.": "Flexibility is built on systems, not random situations.",
    "Sứ mệnh": "Mission",
    "Sứ mệnh của ANSLIFE là xây dựng một hệ thống sản xuất minh bạch, có thể kiểm soát và có khả năng mở rộng toàn cầu, giúp kết nối hiệu quả giữa khách hàng quốc tế và mạng lưới sản xuất.": "ANSLIFE's mission is to build a transparent, controllable and globally scalable production system that effectively connects international customers and production networks.",
    "Tại ANSLIFE, con người không vận hành độc lập. Con người vận hành trong hệ thống.": "At ANSLIFE, people do not operate independently. People operate within the system.",
