    "Tạo nền tảng để người học theo đuổi mục tiêu dài hạn": "Create a foundation for learners to pursue long-term goals",
    "Tạo ra một nền tảng sản xuất có khả năng mở rộng linh hoạt theo nhu cầu thị trường": "Create a production platform that can flexibly expand according to market needs",
