    "Trách nhiệm": "Responsibility",
    "Trách nhiệm này bao gồm chuẩn bị vật liệu, kiểm soát sản xuất, kiểm tra chất lượng, bảo vệ khi đóng gói, chứng từ xuất hàng, phối hợp logistics và phản hồi sau khi hàng đến.": "This responsibility includes material preparation, production control, quality control, packaging protection, shipping documents, logistics coordination and post-arrival feedback.",
