    "Vật liệu, mẫu sơn, bảng màu, veneer, plywood, foam, vải, phụ kiện và vật liệu đóng gói được kiểm soát theo tiêu chuẩn của từng buyer và từng thị trường.": "Materials, paint samples, color palettes, veneer, plywood, foam, fabric, accessories and packaging materials are controlled according to the standards of each buyer and each market.",
