    "Chất lượng được kiểm soát bằng hệ thống, không phụ thuộc vào vị trí địa lý": "地理的な場所に関係なく、品質はシステムによって管理されます",
    "Chất lượng không được đảm bảo bằng lời nói, mà bằng hệ thống kiểm soát xuyên suốt.": "品質は言葉で保証するものではなく、徹底した管理体制で保証します。",
    "Chất lượng không được đảm bảo bằng lời nói. Chất lượng được đảm bảo bằng hệ thống kiểm soát.": "品質は口頭で保証されません。品質は管理システムによって保証されます。",
