    "chuỗi cung ứng vật liệu": "材料サプライチェーン",
    "Chuỗi khép kín": "クローズドチェーン",
    "Chuyển trụ sở chính về Thành phố Hồ Chí Minh và mở rộng hệ thống vệ tinh": "本社をホーチミン市に移転し、衛星システムを拡張",
    "Chương trình chào đón nhiều nhóm đối tác với vai trò phù hợp năng lực đóng góp.": "このプログラムは、適切な役割と貢献能力を持つ多くのパートナー グループを歓迎します。",
    "Chương trình được thiết kế để hình thành lực lượng lao động có kỹ năng và kỷ luật vận hành.": "このプログラムは、熟練した業務規律ある労働力を形成するように設計されています。",
    "Chương trình được triển khai cùng trường nghề, đối tác chuyên môn và đội ngũ vận hành nội bộ.": "このプログラムは、専門学校、専門パートナー、社内運用チームと協力して実施されます。",
    "Chương trình học bổng": "奨学金プログラム",
    "Chương trình học bổng ANSLIFE tập trung hỗ trợ học sinh, sinh viên có nỗ lực học tập tốt, ưu tiên nhóm có hoàn cảnh khó khăn và tiềm năng phát triển lâu dài.": "ANSLIFE 奨学金プログラムは、困難な状況にあり長期的な発展の可能性があるグループを優先し、優れた学業努力を積んだ学生のサポートに重点を置いています。",
    "Chương trình học bổng được đánh giá bằng chỉ số đầu ra và mức độ bền vững của tác động.": "奨学金プログラムは、成果指標と影響の持続性によって評価されます。",
    "Chương trình hướng tới trao cơ hội học tập bền vững thay vì hỗ trợ ngắn hạn một lần.": "このプログラムは、一度限りの短期的なサポートではなく、持続可能な学習の機会を提供することを目的としています。",
    "Chương trình ưu tiên nhóm học viên cần hỗ trợ để duy trì và phát triển việc học.": "このプログラムでは、学習の維持と発展のためにサポートが必要な学生のグループを優先します。",
