    "Khảo sát nhu cầu thực địa và xác định nhóm thụ hưởng": "現場のニーズを調査し、受益者グループを特定する",
    "Khi làm việc với một khách hàng, chúng tôi không chỉ nhìn vào đơn hàng hiện tại. Chúng tôi xem xét cách để đơn hàng tiếp theo ổn định hơn, chu kỳ sản xuất tiếp theo hiệu quả hơn và lô hàng tiếp theo đáng tin cậy hơn.": "顧客と協力するとき、私たちは現在の注文だけを見るわけではありません。私たちは、次の注文をより安定させ、次の生産サイクルをより効率的にし、次回の出荷の信頼性を高める方法を検討します。",
    "Khi một vấn đề xảy ra, ANSLIFE không muốn chỉ đóng lại sau một lần sửa chữa. Chúng tôi muốn hiểu đó là lỗi đơn lẻ hay lỗi lặp lại, lỗi đến từ vật liệu, phương pháp sản xuất, phương pháp kiểm tra, đóng gói, logistics hay giao tiếp.": "問題が発生した場合、ANSLIFE は 1 回の修理だけで終了することを望んでいません。私たちは、それが単一のエラーなのか、繰り返し発生するエラーなのか、そのエラーが材料、生産方法、検査方法、梱包、物流、コミュニケーションに起因するのかを理解したいと考えています。",
    "Kho bãi an toàn, quản lý tồn kho và chuẩn bị xuất hàng định kỳ.": "安全な倉庫、在庫管理、定期出荷の準備。",
    "Không chỉ trao học bổng, chúng tôi đồng hành cùng hành trình học tập.": "私たちは奨学金を授与するだけでなく、学習の旅にも同行します。",
