    "Mở rộng xuất khẩu và ra mắt thương hiệu ANSLIFE": "輸出拡大とANSLIFEブランド立ち上げ",
    "Mục tiêu của chúng tôi không chỉ là xuất hàng. Mục tiêu của chúng tôi là giúp khách hàng nhận được sản phẩm ổn định, có thể truy xuất và đáng tin cậy.": "私たちの目標は商品を発送することだけではありません。私たちの目標は、お客様が安定して追跡可能で信頼性の高い製品を受け取れるよう支援することです。",
    "Mục tiêu của quỹ": "基金の目的",
