    "Quỹ được thiết kế với mục tiêu rõ ràng, đo lường được và có tính liên tục qua từng năm.": "この基金は、毎年明確で測定可能な継続的な目標を設定して設計されています。",
    "Quỹ được xây theo lộ trình dài hạn, gắn với chiến lược phát triển cộng đồng của ANSLIFE.": "この基金は、ANSLIFE のコミュニティ開発戦略に関連した長期ロードマップに従って構築されています。",
    "Quỹ học bổng": "奨学金基金",
    "Quỹ học bổng và cộng đồng ANSLIFE được xây dựng như một chương trình phát triển bền vững, tập trung hỗ trợ giáo dục và tạo tác động tích cực lâu dài cho địa phương.": "ANSLIFE 奨学金およびコミュニティ基金は、教育を支援し、地域に長期的なプラスの影響を生み出すことに焦点を当てた、持続可能な開発プログラムとして構築されています。",
    "Quỹ không chỉ hỗ trợ tài chính mà còn thúc đẩy cơ hội học tập bền vững.": "財団は財政的支援を提供するだけでなく、持続可能な学習の機会も促進します。",
    "Quy trình được thiết kế ngắn gọn nhưng có kiểm soát để bảo đảm tính minh bạch.": "プロセスは簡潔になるように設計されていますが、透明性を確保するために制御されています。",
