    "Trách nhiệm này bao gồm chuẩn bị vật liệu, kiểm soát sản xuất, kiểm tra chất lượng, bảo vệ khi đóng gói, chứng từ xuất hàng, phối hợp logistics và phản hồi sau khi hàng đến.": "この責任には、材料の準備、生産管理、品質管理、梱包保護、出荷書類、物流調整、到着後のフィードバックが含まれます。",
