    "Vật liệu, mẫu sơn, bảng màu, veneer, plywood, foam, vải, phụ kiện và vật liệu đóng gói được kiểm soát theo tiêu chuẩn của từng buyer và từng thị trường.": "材料、塗料サンプル、カラーパレット、ベニヤ、合板、フォーム、生地、付属品および梱包材は、各バイヤーおよび各市場の基準に従って管理されます。",
