    "Chọn nhóm vật liệu, sau đó vào từng mục con để xem chi tiết.": "재료 그룹을 선택한 다음 각 하위 섹션으로 이동하여 세부 정보를 확인하세요.",
    "Chu kỳ đánh giá và cải tiến": "평가 및 개선주기",
