    "Chuẩn hóa quy trình và hệ thống kiểm soát chất lượng": "프로세스 및 품질 관리 시스템 표준화",
    "Chuẩn hóa và phân phối dữ liệu": "데이터 정규화 및 배포",
    "Chúng tôi hướng đến sự phát triển bền vững thông qua việc đầu tư vào con người, nâng cao năng lực sản xuất, hỗ trợ cộng đồng và xây dựng chuỗi cung ứng có trách nhiệm.": "우리는 사람에 대한 투자, 생산 능력 향상, 지역 사회 지원 및 책임 있는 공급망 구축을 통해 지속 가능한 개발을 목표로 합니다.",
    "Chúng tôi hướng tới đội ngũ:": "우리는 팀을 목표로 합니다.",
    "Chúng tôi hướng tới:": "우리의 목표는 다음과 같습니다.",
    "Chúng tôi không chỉ bán sản phẩm, mà cung cấp giải pháp sản xuất phù hợp với từng thị trường.": "단순히 제품을 판매하는 것이 아닌 각 시장에 적합한 생산 솔루션을 제공합니다.",
    "Chúng tôi không chỉ xây dựng năng lực sản xuất tại Việt Nam, mà từng bước mở rộng hệ sinh thái sang các khu vực khác, nơi các nhà máy được tổ chức và vận hành theo cùng một tiêu chuẩn, cùng một hệ thống kiểm soát và cùng một phương thức quản lý dữ liệu.": "베트남에서 생산능력을 구축하는 것뿐만 아니라, 동일한 기준, 동일한 제어 시스템, 동일한 데이터 관리 방법에 따라 공장을 구성하고 운영하는 다른 지역으로도 생태계를 점차 확장합니다.",
    "Chúng tôi không tách rời con người khỏi hệ thống.": "우리는 시스템에서 사람을 분리하지 않습니다.",
    "Chúng tôi quản lý công việc không chỉ bằng trao đổi miệng, mà còn thông qua thư mục dự án, bảng tiến độ, báo cáo kiểm tra, hình ảnh, hồ sơ giao hàng và nhật ký lỗi.": "말로만 하는 것이 아니라 프로젝트 폴더, 진도표, 검사 보고서, 사진, 납품 기록, 오류 로그 등을 통해 업무를 관리합니다.",
    "Chúng tôi sẽ tiếp tục cải thiện hệ thống sản xuất, kiểm soát chuỗi cung ứng, quản lý chất lượng, theo dõi dự án và giao tiếp với khách hàng.": "우리는 생산 시스템, 공급망 관리, 품질 관리, 프로젝트 추적 및 고객 커뮤니케이션을 지속적으로 개선해 나갈 것입니다.",
    "Chúng tôi tin rằng một công ty tốt không phải là công ty không có vấn đề. Một công ty tốt là công ty có thể học từ vấn đề và trở nên đáng tin cậy hơn theo thời gian.": "우리는 좋은 회사는 문제가 없는 회사가 아니라고 믿습니다. 좋은 회사는 문제로부터 배울 수 있고 시간이 지남에 따라 더욱 신뢰할 수 있는 회사입니다.",
    "Chúng tôi tin rằng sự cố ngoài dự kiến có thể xảy ra ở bất kỳ công đoạn nào trong sản xuất hoặc vận chuyển. Vì vậy, ANSLIFE xây dựng hệ thống dự phòng và kế hoạch bảo vệ để hấp thụ rủi ro và bảo vệ dự án.": "우리는 생산이나 운송의 모든 단계에서 예상치 못한 사고가 발생할 수 있다고 믿습니다. 따라서 ANSLIFE는 위험을 흡수하고 프로젝트를 보호하기 위해 백업 시스템과 보호 계획을 구축합니다.",
    "Chúng tôi vận hành một hệ thống gồm nhà máy do ANSLIFE điều phối, mạng lưới nhà máy vệ tinh, chuỗi cung ứng vật liệu liên tục, hệ thống QC độc lập, kho lưu trữ tại Việt Nam và cơ chế xuất hàng định kỳ.": "ANSLIFE가 연계한 공장, 위성 공장 네트워크, 지속적인 자재 공급망, 독립적인 QC 시스템, 베트남 보관 및 정기 배송 메커니즘을 포함한 시스템을 운영하고 있습니다.",
    "Chúng tôi vận hành theo mô hình hệ sinh thái sản xuất được kiểm soát tập trung.": "우리는 중앙에서 통제되는 제조 생태계 모델에 따라 운영됩니다.",
    "Chúng tôi xây dựng một hệ sinh thái sản xuất có thể mở rộng.": "우리는 확장 가능한 제조 생태계를 구축합니다.",
    "Chuỗi cung ứng ổn định & linh hoạt": "안정적이고 유연한 공급망",
    "chuỗi cung ứng vật liệu": "자재 공급망",
    "Chuỗi khép kín": "폐쇄형 체인",
    "Chuyển trụ sở chính về Thành phố Hồ Chí Minh và mở rộng hệ thống vệ tinh": "호치민으로 본사 이전 및 위성시스템 확충",
    "Chương trình chào đón nhiều nhóm đối tác với vai trò phù hợp năng lực đóng góp.": "이 프로그램은 적절한 역할과 기여 역량을 갖춘 많은 파트너 그룹을 환영합니다.",
    "Chương trình được thiết kế để hình thành lực lượng lao động có kỹ năng và kỷ luật vận hành.": "이 프로그램은 숙련되고 운영상 훈련된 인력을 형성하도록 설계되었습니다.",
    "Chương trình được triển khai cùng trường nghề, đối tác chuyên môn và đội ngũ vận hành nội bộ.": "이 프로그램은 직업 학교, 전문 파트너 및 내부 운영 팀과 함께 시행됩니다.",
    "Chương trình học bổng": "장학금 제도",
    "Chương trình học bổng ANSLIFE tập trung hỗ trợ học sinh, sinh viên có nỗ lực học tập tốt, ưu tiên nhóm có hoàn cảnh khó khăn và tiềm năng phát triển lâu dài.": "ANSLIFE 장학금 프로그램은 어려운 상황과 장기적인 발전 잠재력을 지닌 그룹을 우선적으로 학업에 전념하는 학생들을 지원하는 데 중점을 두고 있습니다.",
    "Chương trình học bổng được đánh giá bằng chỉ số đầu ra và mức độ bền vững của tác động.": "장학사업은 성과지표와 영향력의 지속가능성을 기준으로 평가됩니다.",
    "Chương trình hướng tới trao cơ hội học tập bền vững thay vì hỗ trợ ngắn hạn một lần.": "이 프로그램은 일회성 단기 지원이 아닌 지속 가능한 학습 기회를 제공하는 것을 목표로 합니다.",
    "Chương trình ưu tiên nhóm học viên cần hỗ trợ để duy trì và phát triển việc học.": "이 프로그램은 학습을 유지하고 발전시키기 위해 지원이 필요한 학생 그룹에 우선순위를 둡니다.",
