    "Đào tạo kỹ năng nghề và an toàn làm việc": "직업 기술 및 산업 안전 교육",
    "Đào tạo kỹ năng nghề, phát triển đội ngũ quản lý và nâng cao năng lực sản xuất.": "직업 기술 훈련, 관리 팀 개발 및 생산 능력 향상.",
    "Đào tạo kỹ năng số và quản trị dữ liệu cơ bản": "디지털 기초 기술 및 데이터 관리 교육",
    "Đào tạo thực tế trong sản xuất": "제작실습",
    "Đầu tư cho con người là nền tảng của phát triển dài hạn.": "사람에 대한 투자는 장기적인 발전의 기초입니다.",
    "Đầu tư con người": "사람에게 투자하다",
    "Đầu tư vào con người để tạo năng lực vận hành bền vững cho cộng đồng và doanh nghiệp.": "지역사회와 기업을 위한 지속 가능한 운영 역량을 창출하기 위해 인력에 투자합니다.",
    "Đầu tư vào đào tạo, môi trường làm việc và cơ hội phát triển cho đội ngũ nhân sự.": "직원을 위한 교육, 작업 환경 및 개발 기회에 투자합니다.",
    "Đây là bước phát triển quan trọng trong việc tách hoạt động kiểm soát chất lượng khỏi bộ máy sản xuất, giúp ANSLIFE nâng cao tính khách quan, khả năng truy xuất và mức độ kiểm soát trong các đơn hàng xuất khẩu.": "이는 생산 장치에서 품질 관리 활동을 분리하는 중요한 발전으로, ANSLIFE가 수출 주문의 객관성, 추적성 및 통제 수준을 향상시키는 데 도움이 됩니다.",
    "Đây là giai đoạn ANSLIFE mở rộng từ sản xuất nội thất sang thiết kế, tư vấn và triển khai không gian nội thất hoàn chỉnh.": "ANSLIFE가 가구 제작부터 디자인, 컨설팅, 완전한 인테리어 공간 구현까지 영역을 확장한 시기입니다.",
    "Đây là lõi vận hành của hệ thống ANSLIFE.": "ANSLIFE 시스템의 운영핵심입니다.",
    "Đây là lý do ANSLIFE chuẩn hóa việc kiểm soát vật liệu, chuẩn bị hàng trắng, kiểm tra mộng liên kết, kiểm soát hoàn thiện sơn, bảo vệ đóng gói, bảng tiến độ dự án và hồ sơ lỗi xuyên đơn hàng.": "이것이 바로 ANSLIFE가 자재 관리, 백색 가전 준비, 공동 검사, 페인트 마감 관리, 포장 보호, 프로젝트 일정 시트 및 교차 주문 결함 기록을 표준화하는 이유입니다.",
    "Đây là lý do ANSLIFE tiếp tục đầu tư vào kiểm soát vật liệu, kế hoạch sản xuất, kiểm tra chất lượng, tiêu chuẩn đóng gói, theo dõi dự án và hồ sơ cải tiến.": "이것이 ANSLIFE가 자재 관리, 생산 계획, 품질 검사, 포장 표준, 프로젝트 추적 및 개선 기록에 지속적으로 투자하는 이유입니다.",
    "Đây là một cột mốc quan trọng, vì thị trường Nhật Bản có yêu cầu cao về chất lượng, độ ổn định, tiêu chuẩn đóng gói, kiểm soát chi tiết và khả năng duy trì tiêu chuẩn sản phẩm trong dài hạn.": "일본 시장은 품질, 안정성, 포장 표준, 세부적인 제어 및 장기적으로 제품 표준을 유지하는 능력에 대한 높은 요구 사항을 갖고 있기 때문에 이는 중요한 이정표입니다.",
    "Đây là nền tảng quan trọng để ANSLIFE phát triển hệ thống": "ANSLIFE가 시스템을 개발하는데 중요한 기반이 됩니다.",
    "Đây là trung tâm kiểm soát toàn bộ hoạt động của ANSLIFE.": "ANSLIFE의 모든 업무를 총괄하는 센터입니다.",
    "Đề xuất điều chỉnh về kết cấu, vật liệu, màu sơn và khả năng sản xuất": "구조, 재료, 페인트 색상 및 제조 능력에 대한 조정을 제안합니다.",
    "Đến giai đoạn này, ANSLIFE sở hữu năng lực sản xuất thông qua hệ thống nhà máy vệ tinh đa dạng, mạng lưới cung cấp nguyên liệu và kinh nghiệm vận hành các đơn hàng xuất khẩu.": "현 단계에서 ANSLIFE는 다양한 위성공장 시스템과 원자재 공급망, 수출주문 운영 경험을 통해 생산능력을 보유하고 있습니다.",
