    "Đội ngũ QC bao gồm:": "QC 팀에는 다음이 포함됩니다.",
    "Đội ngũ thương mại của ANSLIFE vận hành dựa trên dữ liệu thực tế.": "ANSLIFE의 상업팀은 실제 데이터를 기반으로 운영됩니다.",
    "Đối tác": "파트너",
