    "Đối tác sản xuất, chuỗi cung ứng & xuất khẩu": "제조, 공급망 및 수출 파트너",
    "Đối tác sản xuất, chuỗi cung ứng và xuất khẩu tại Việt Nam": "베트남의 제조, 공급망 및 수출 파트너",
    "Đối tác thương mại": "거래처",
    "Đối tượng có thể tham gia": "피험자가 참여할 수 있습니다.",
    "Đối tượng ưu tiên": "우선순위 객체",
    "Đối với ANSLIFE, dữ liệu không chỉ dùng để báo cáo. Dữ liệu là công cụ làm việc để ra quyết định tốt hơn, kiểm soát chất lượng tốt hơn và quản lý dự án tốt hơn.": "ANSLIFE의 경우 데이터는 보고만을 위한 것이 아닙니다. 데이터는 더 나은 의사결정, 더 나은 품질 관리, 더 나은 프로젝트 관리를 위한 작업 도구입니다.",
    "Đối với ANSLIFE, niềm tin không được tạo ra chỉ bằng lời nói. Niềm tin được tạo ra bằng hành động hằng ngày, dữ liệu rõ ràng, trách nhiệm được lặp lại và tinh thần sẵn sàng cải tiến sau mỗi dự án.": "ANSLIFE에게 신뢰는 말로만 만들어지는 것이 아닙니다. 매일의 행동, 명확한 데이터, 반복 가능한 책임, 각 프로젝트를 통해 개선하려는 의지를 통해 신뢰가 형성됩니다.",
    "Đối với chúng tôi, niềm tin dài hạn phải được xây dựng bằng trách nhiệm được lặp lại, dữ liệu minh bạch, cải tiến liên tục và những hành động thực tế trong vận hành hằng ngày.": "우리에게는 반복적인 책임, 투명한 데이터, 지속적인 개선 및 일상 업무에서의 실제 조치를 통해 장기적인 신뢰가 구축되어야 합니다.",
