    "Khi làm việc với một khách hàng, chúng tôi không chỉ nhìn vào đơn hàng hiện tại. Chúng tôi xem xét cách để đơn hàng tiếp theo ổn định hơn, chu kỳ sản xuất tiếp theo hiệu quả hơn và lô hàng tiếp theo đáng tin cậy hơn.": "고객과 작업할 때 우리는 현재 주문만 보지 않습니다. 우리는 다음 주문을 보다 안정적으로 만들고, 다음 생산 주기를 보다 효율적으로 만들고, 다음 배송을 보다 안정적으로 만드는 방법을 살펴봅니다.",
    "Khi một vấn đề xảy ra, ANSLIFE không muốn chỉ đóng lại sau một lần sửa chữa. Chúng tôi muốn hiểu đó là lỗi đơn lẻ hay lỗi lặp lại, lỗi đến từ vật liệu, phương pháp sản xuất, phương pháp kiểm tra, đóng gói, logistics hay giao tiếp.": "문제가 발생하면 ANSLIFE는 한 번의 수리 후에 단순히 종료되는 것을 원하지 않습니다. 우리는 그것이 단일 오류인지 반복적인 오류인지, 그 오류가 자재, 생산 방법, 검사 방법, 포장, 물류 또는 통신에서 비롯되는지 이해하고 싶습니다.",
