    "Quỹ được thiết kế với mục tiêu rõ ràng, đo lường được và có tính liên tục qua từng năm.": "기금은 해마다 명확하고 측정 가능하며 지속적인 목표를 가지고 설계되었습니다.",
    "Quỹ được xây theo lộ trình dài hạn, gắn với chiến lược phát triển cộng đồng của ANSLIFE.": "이 기금은 ANSLIFE의 커뮤니티 개발 전략과 관련된 장기 로드맵에 따라 구축되었습니다.",
    "Quỹ học bổng": "장학금",
    "Quỹ học bổng và cộng đồng ANSLIFE được xây dựng như một chương trình phát triển bền vững, tập trung hỗ trợ giáo dục và tạo tác động tích cực lâu dài cho địa phương.": "ANSLIFE 장학금 및 커뮤니티 기금은 지속 가능한 개발 프로그램으로 구축되었으며, 교육을 지원하고 지역에 장기적으로 긍정적인 영향을 미치는 데 중점을 두고 있습니다.",
