    "Trách nhiệm này bao gồm chuẩn bị vật liệu, kiểm soát sản xuất, kiểm tra chất lượng, bảo vệ khi đóng gói, chứng từ xuất hàng, phối hợp logistics và phản hồi sau khi hàng đến.": "이 책임에는 자재 준비, 생산 관리, 품질 관리, 포장 보호, 배송 문서, 물류 조정 및 도착 후 피드백이 포함됩니다.",
