    "Bộ phận điều hành và thương mại": "Drift och kommersiell avdelning",
    "Bộ phận này đảm bảo dữ liệu chính xác, thông tin minh bạch và vận hành không phụ thuộc cảm tính.": "Denna avdelning säkerställer korrekt data, transparent information och operationer som inte är beroende av känslor.",
    "Bộ phận pháp chế": "Juridisk avdelning",
    "Bộ phận pháp chế giúp giảm thiểu rủi ro pháp lý, tăng độ tin cậy với đối tác quốc tế và đảm bảo hoạt động xuất khẩu ổn định.": "Den juridiska avdelningen hjälper till att minimera juridiska risker, öka tillförlitligheten med internationella partners och säkerställa stabila exportaktiviteter.",
