    "Buyer có thể liên hệ ANSLIFE để gửi yêu cầu sản phẩm, bản vẽ, mẫu, vật liệu hoặc kế hoạch lưu kho – xuất hàng từ Việt Nam.": "Köpare kan kontakta ANSLIFE för att skicka produktförfrågningar, ritningar, prover, material eller lagringsplaner - exportera varor från Vietnam.",
