    "Các nhóm nội dung": "Innehållsgrupper",
    "Các nhóm sản phẩm xuất khẩu bao gồm sản phẩm làm từ gỗ tự nhiên, MDF, plywood và các vật liệu phục vụ sản xuất nội thất.": "Exportproduktgrupper inkluderar produkter tillverkade av naturligt trä, MDF, plywood och material för möbelproduktion.",
    "Các thị trường chính:": "Huvudmarknader:",
