    "Chất lượng": "Kvalitet",
    "Chất lượng & Tiêu chuẩn": "Kvalitet och standarder",
    "Chất lượng được kiểm soát bằng hệ thống, không phụ thuộc vào vị trí địa lý": "Kvaliteten styrs av systemet, oavsett geografisk plats",
    "Chất lượng không được đảm bảo bằng lời nói, mà bằng hệ thống kiểm soát xuyên suốt.": "Kvalitet garanteras inte med ord, utan av ett noggrant kontrollsystem.",
    "Chất lượng không được đảm bảo bằng lời nói. Chất lượng được đảm bảo bằng hệ thống kiểm soát.": "Kvalitet kan inte garanteras muntligt. Kvalitet garanteras av kontrollsystem.",
    "Châu Âu": "Europa",
    "Checklist kiểm hàng": "Checklista för kontroll av varor",
    "Chia sẻ kinh nghiệm, quy trình và tiêu chuẩn nhằm nâng cao năng lực của chuỗi cung ứng.": "Dela erfarenheter, processer och standarder för att förbättra leveranskedjans kapacitet.",
    "Chia sẻ theo đúng phạm vi": "Dela inom rätt omfattning",
    "cho buyer quốc tế.": "för internationella köpare.",
    "Chọn nhóm vật liệu, sau đó vào từng mục con để xem chi tiết.": "Välj en materialgrupp och gå sedan till varje undersektion för att se detaljer.",
    "Chu kỳ đánh giá và cải tiến": "Utvärderings- och förbättringscykel",
    "Chuẩn bị vật liệu & phát triển mẫu": "Materialberedning och provutveckling",
    "Chuẩn hóa quy trình và hệ thống kiểm soát chất lượng": "Standardisera processer och kvalitetskontrollsystem",
    "Chuẩn hóa và phân phối dữ liệu": "Normalisera och distribuera data",
    "Chúng tôi hướng đến sự phát triển bền vững thông qua việc đầu tư vào con người, nâng cao năng lực sản xuất, hỗ trợ cộng đồng và xây dựng chuỗi cung ứng có trách nhiệm.": "Vi strävar efter hållbar utveckling genom att investera i människor, förbättra produktionskapaciteten, stödja samhället och bygga en ansvarsfull försörjningskedja.",
    "Chúng tôi hướng tới đội ngũ:": "Vi siktar på laget:",
    "Chúng tôi hướng tới:": "Vi strävar efter att:",
    "Chúng tôi không chỉ bán sản phẩm, mà cung cấp giải pháp sản xuất phù hợp với từng thị trường.": "Vi säljer inte bara produkter, utan tillhandahåller produktionslösningar som passar varje marknad.",
    "Chúng tôi không chỉ xây dựng năng lực sản xuất tại Việt Nam, mà từng bước mở rộng hệ sinh thái sang các khu vực khác, nơi các nhà máy được tổ chức và vận hành theo cùng một tiêu chuẩn, cùng một hệ thống kiểm soát và cùng một phương thức quản lý dữ liệu.": "Vi bygger inte bara produktionskapacitet i Vietnam, utan utökar gradvis ekosystemet till andra regioner, där fabriker är organiserade och drivs enligt samma standarder, samma kontrollsystem och samma datahanteringsmetod.",
    "Chúng tôi không tách rời con người khỏi hệ thống.": "Vi separerar inte människor från systemet.",
    "Chúng tôi quản lý công việc không chỉ bằng trao đổi miệng, mà còn thông qua thư mục dự án, bảng tiến độ, báo cáo kiểm tra, hình ảnh, hồ sơ giao hàng và nhật ký lỗi.": "Vi hanterar arbetet inte bara verbalt, utan också genom projektmappar, förloppsblad, inspektionsrapporter, foton, leveransprotokoll och felloggar.",
    "Chúng tôi sẽ tiếp tục cải thiện hệ thống sản xuất, kiểm soát chuỗi cung ứng, quản lý chất lượng, theo dõi dự án và giao tiếp với khách hàng.": "Vi kommer att fortsätta att förbättra vårt produktionssystem, kontroll av försörjningskedjan, kvalitetsstyrning, projektspårning och kundkommunikation.",
    "Chúng tôi tin rằng một công ty tốt không phải là công ty không có vấn đề. Một công ty tốt là công ty có thể học từ vấn đề và trở nên đáng tin cậy hơn theo thời gian.": "Vi tror att ett bra företag inte är ett företag utan problem. Ett bra företag är ett som kan lära av problem och bli mer pålitligt med tiden.",
    "Chúng tôi tin rằng sự cố ngoài dự kiến có thể xảy ra ở bất kỳ công đoạn nào trong sản xuất hoặc vận chuyển. Vì vậy, ANSLIFE xây dựng hệ thống dự phòng và kế hoạch bảo vệ để hấp thụ rủi ro và bảo vệ dự án.": "Vi tror att oväntade incidenter kan inträffa i alla skeden av produktion eller transport. Därför bygger ANSLIFE backupsystem och skyddsplaner för att absorbera risker och skydda projektet.",
    "Chúng tôi vận hành một hệ thống gồm nhà máy do ANSLIFE điều phối, mạng lưới nhà máy vệ tinh, chuỗi cung ứng vật liệu liên tục, hệ thống QC độc lập, kho lưu trữ tại Việt Nam và cơ chế xuất hàng định kỳ.": "Vi driver ett system som inkluderar fabriker koordinerade av ANSLIFE, satellitfabriksnätverk, kontinuerlig materialförsörjningskedja, oberoende QC-system, lagring i Vietnam och mekanism för periodisk leverans.",
    "Chúng tôi vận hành theo mô hình hệ sinh thái sản xuất được kiểm soát tập trung.": "Vi arbetar under en centralt styrd tillverkningsekosystemmodell.",
    "Chúng tôi xây dựng một hệ sinh thái sản xuất có thể mở rộng.": "Vi bygger ett skalbart tillverkningsekosystem.",
    "Chuỗi cung ứng ổn định & linh hoạt": "Stabil och flexibel leveranskedja",
    "chuỗi cung ứng vật liệu": "materialförsörjningskedja",
    "Chuỗi khép kín": "Sluten kedja",
    "Chuyển trụ sở chính về Thành phố Hồ Chí Minh và mở rộng hệ thống vệ tinh": "Flyttade högkvarter till Ho Chi Minh City och utökade satellitsystem",
    "Chương trình chào đón nhiều nhóm đối tác với vai trò phù hợp năng lực đóng góp.": "Programmet välkomnar många grupper av partner med lämpliga roller och bidragande kapacitet.",
    "Chương trình được thiết kế để hình thành lực lượng lao động có kỹ năng và kỷ luật vận hành.": "Programmet är utformat för att bilda en skicklig och operativt disciplinerad arbetsstyrka.",
    "Chương trình được triển khai cùng trường nghề, đối tác chuyên môn và đội ngũ vận hành nội bộ.": "Programmet genomförs med yrkesskolor, professionella partners och interna verksamhetsteam.",
    "Chương trình học bổng": "Stipendiumsprogram",
    "Chương trình học bổng ANSLIFE tập trung hỗ trợ học sinh, sinh viên có nỗ lực học tập tốt, ưu tiên nhóm có hoàn cảnh khó khăn và tiềm năng phát triển lâu dài.": "ANSLIFEs stipendieprogram fokuserar på att stödja studenter med goda akademiska insatser, prioritera grupper med svåra förutsättningar och långsiktig utvecklingspotential.",
    "Chương trình học bổng được đánh giá bằng chỉ số đầu ra và mức độ bền vững của tác động.": "Stipendiets program utvärderas av resultatindikatorer och hållbarhet i påverkan.",
    "Chương trình hướng tới trao cơ hội học tập bền vững thay vì hỗ trợ ngắn hạn một lần.": "Programmet syftar till att ge hållbara lärandemöjligheter istället för engångsstöd på kort sikt.",
    "Chương trình ưu tiên nhóm học viên cần hỗ trợ để duy trì và phát triển việc học.": "Programmet prioriterar grupper av elever som behöver stöd för att upprätthålla och utveckla sitt lärande.",
