    "Dù sản xuất tại bất kỳ nhà máy nào, mọi hoạt động đều phải tuân theo:": "Oavsett produktion på någon fabrik måste alla aktiviteter följa:",
    "Duy trì chất lượng ổn định trên toàn hệ thống": "Upprätthåll stabil kvalitet i hela systemet",
    "Duy trì kênh phản hồi trực tiếp từ cộng đồng thụ hưởng": "Upprätthåll en direkt återkopplingskanal från mottagargemenskapen",
    "DỮ LIỆU": "DATA",
    "Dữ liệu bao gồm:": "Data inkluderar:",
    "Dữ liệu được cập nhật theo thời gian thực, kiểm soát trước khi chia sẻ và phân quyền theo từng tài khoản.": "Data uppdateras i realtid, kontrolleras före delning och godkänns av varje konto.",
    "Dữ liệu được luân chuyển theo nguyên tắc:": "Data cirkuleras enligt principen:",
    "Dữ liệu không chỉ để lưu trữ, mà để:": "Data är inte bara för lagring, utan för:",
    "Dữ liệu lỗi": "Feldata",
    "Dữ liệu QC": "QC-data",
    "Dữ liệu QC được ghi nhận trực tiếp tại hiện trường, lưu trữ trên hệ thống và kiểm soát nhiều lớp trước khi sử dụng.": "QC-data spelas in direkt på platsen, lagras i systemet och kontrolleras i många lager före användning.",
    "Dữ liệu sản xuất": "Produktionsdata",
