    "Đảm bảo chất lượng và tiến độ ở quy mô lớn": "Säkerställa kvalitet och framsteg i stor skala",
    "Đảm bảo dữ liệu cung cấp cho sale và khách hàng là dữ liệu đã được kiểm soát": "Se till att data som tillhandahålls till försäljning och kunder är kontrollerad data",
    "Đảm bảo quyền lợi của các bên tham gia": "Säkerställa rättigheterna för deltagande parter",
    "Đảm bảo sản phẩm đạt yêu cầu trước khi xuất hàng": "Se till att produkter uppfyller kraven innan de skickas",
    "Đánh giá đầu ra theo chỉ số đã cam kết": "Utvärdera output enligt engagerade indikatorer",
    "Đánh giá năng lực theo tiêu chí thống nhất": "Utvärdera kapacitet enligt enhetliga kriterier",
    "Đánh giá tác động sau chương trình": "Utvärdera effekten efter programmet",
    "Đánh giá theo bộ tiêu chí đã công bố": "Utvärderad enligt de publicerade kriterierna",
    "Đào tạo kỹ năng mềm và tác phong nghề nghiệp": "Mjuka färdigheter och professionell beteendeträning",
    "Đào tạo kỹ năng nghề và an toàn làm việc": "Yrkeskompetens och arbetssäkerhetsutbildning",
    "Đào tạo kỹ năng nghề, phát triển đội ngũ quản lý và nâng cao năng lực sản xuất.": "Yrkesutbildning, ledningsgruppsutveckling och förbättring av produktionskapaciteten.",
    "Đào tạo kỹ năng số và quản trị dữ liệu cơ bản": "Utbildning i grundläggande digitala färdigheter och datahantering",
    "Đào tạo thực tế trong sản xuất": "Praktisk utbildning i produktion",
    "Đầu tư cho con người là nền tảng của phát triển dài hạn.": "Att investera i människor är grunden för långsiktig utveckling.",
    "Đầu tư con người": "Investera i människor",
    "Đầu tư vào con người để tạo năng lực vận hành bền vững cho cộng đồng và doanh nghiệp.": "Investera i människor för att skapa hållbar verksamhetskapacitet för samhällen och företag.",
    "Đầu tư vào đào tạo, môi trường làm việc và cơ hội phát triển cho đội ngũ nhân sự.": "Satsa på utbildning, arbetsmiljö och utvecklingsmöjligheter för personalen.",
    "Đây là bước phát triển quan trọng trong việc tách hoạt động kiểm soát chất lượng khỏi bộ máy sản xuất, giúp ANSLIFE nâng cao tính khách quan, khả năng truy xuất và mức độ kiểm soát trong các đơn hàng xuất khẩu.": "Detta är en viktig utveckling för att separera kvalitetskontrollaktiviteter från produktionsapparaten, vilket hjälper ANSLIFE att förbättra objektiviteten, spårbarheten och kontrollnivån i exportorder.",
    "Đây là giai đoạn ANSLIFE mở rộng từ sản xuất nội thất sang thiết kế, tư vấn và triển khai không gian nội thất hoàn chỉnh.": "Detta är den period då ANSLIFE expanderade från möbelproduktion till design, rådgivning och implementering av kompletta interiörer.",
    "Đây là lõi vận hành của hệ thống ANSLIFE.": "Detta är kärnan i ANSLIFE-systemet.",
    "Đây là lý do ANSLIFE chuẩn hóa việc kiểm soát vật liệu, chuẩn bị hàng trắng, kiểm tra mộng liên kết, kiểm soát hoàn thiện sơn, bảo vệ đóng gói, bảng tiến độ dự án và hồ sơ lỗi xuyên đơn hàng.": "Det är därför ANSLIFE standardiserar materialkontroll, förberedelse av vitvaror, gemensam inspektion, målningskontroll, förpackningsskydd, projektschemablad och korsorderdefektregister.",
    "Đây là lý do ANSLIFE tiếp tục đầu tư vào kiểm soát vật liệu, kế hoạch sản xuất, kiểm tra chất lượng, tiêu chuẩn đóng gói, theo dõi dự án và hồ sơ cải tiến.": "Det är därför ANSLIFE fortsätter att investera i materialkontroll, produktionsplanering, kvalitetsinspektion, förpackningsstandarder, projektspårning och förbättringsrekord.",
    "Đây là một cột mốc quan trọng, vì thị trường Nhật Bản có yêu cầu cao về chất lượng, độ ổn định, tiêu chuẩn đóng gói, kiểm soát chi tiết và khả năng duy trì tiêu chuẩn sản phẩm trong dài hạn.": "Detta är en viktig milstolpe, eftersom den japanska marknaden har höga krav på kvalitet, stabilitet, förpackningsstandarder, detaljerad kontroll och förmågan att upprätthålla produktstandarder på lång sikt.",
    "Đây là nền tảng quan trọng để ANSLIFE phát triển hệ thống": "Detta är en viktig grund för att ANSLIFE ska utveckla systemet",
    "Đây là trung tâm kiểm soát toàn bộ hoạt động của ANSLIFE.": "Detta är centret som kontrollerar alla ANSLIFE-operationer.",
    "Đề xuất điều chỉnh về kết cấu, vật liệu, màu sơn và khả năng sản xuất": "Föreslå justeringar av struktur, material, färgfärger och tillverkningskapacitet",
    "Đến giai đoạn này, ANSLIFE sở hữu năng lực sản xuất thông qua hệ thống nhà máy vệ tinh đa dạng, mạng lưới cung cấp nguyên liệu và kinh nghiệm vận hành các đơn hàng xuất khẩu.": "I detta skede har ANSLIFE produktionskapacitet genom ett mångsidigt satellitfabrikssystem, råvaruförsörjningsnätverk och erfarenhet av att driva exportorder.",
