    "Đối tác thương mại": "Handelspartners",
    "Đối tượng có thể tham gia": "Ämnen kan delta",
    "Đối tượng ưu tiên": "Prioritetsobjekt",
    "Đối với ANSLIFE, dữ liệu không chỉ dùng để báo cáo. Dữ liệu là công cụ làm việc để ra quyết định tốt hơn, kiểm soát chất lượng tốt hơn và quản lý dự án tốt hơn.": "För ANSLIFE är data inte bara för rapportering. Data är ett arbetsverktyg för bättre beslutsfattande, bättre kvalitetskontroll och bättre projektledning.",
    "Đối với ANSLIFE, niềm tin không được tạo ra chỉ bằng lời nói. Niềm tin được tạo ra bằng hành động hằng ngày, dữ liệu rõ ràng, trách nhiệm được lặp lại và tinh thần sẵn sàng cải tiến sau mỗi dự án.": "För ANSLIFE skapas tillit inte bara av ord. Förtroende skapas med dagliga åtgärder, tydliga data, repeterbar ansvarsskyldighet och en vilja att förbättra med varje projekt.",
    "Đối với chúng tôi, niềm tin dài hạn phải được xây dựng bằng trách nhiệm được lặp lại, dữ liệu minh bạch, cải tiến liên tục và những hành động thực tế trong vận hành hằng ngày.": "För oss måste långsiktigt förtroende byggas upp med upprepad ansvarighet, transparenta data, ständiga förbättringar och verkliga åtgärder i den dagliga verksamheten.",
