    "Hệ thống kiểm soát chất lượng": "Kvalitetskontrollsystem",
    "Hệ thống kiểm soát chất lượng (QC)": "Kvalitetskontrollsystem (QC)",
    "Hệ thống này giúp giảm rủi ro pháp lý, tăng độ tin cậy với đối tác và đảm bảo hoạt động dài hạn.": "Detta system hjälper till att minska juridiska risker, öka tillförlitligheten med partners och säkerställa långsiktig verksamhet.",
