    "Kết quả chương trình được đánh giá theo chu kỳ quý và năm để liên tục nâng chất lượng hoạt động.": "Programresultaten utvärderas på kvartals- och årsbasis för att kontinuerligt förbättra verksamhetens kvalitet.",
    "Khách hàng": "Kunder",
    "Khách hàng (Buyer)": "Kund (Köpare)",
    "Khách hàng truy cập thông tin": "Kunder får tillgång till information",
    "Khám phá mô hình hoạt động và năng lực của ANSLIFE.": "Utforska ANSLIFEs verksamhetsmodell och kapacitet.",
    "Khảo sát nhu cầu thực địa và xác định nhóm thụ hưởng": "Undersök fältbehov och identifiera stödmottagargrupper",
    "Khi làm việc với một khách hàng, chúng tôi không chỉ nhìn vào đơn hàng hiện tại. Chúng tôi xem xét cách để đơn hàng tiếp theo ổn định hơn, chu kỳ sản xuất tiếp theo hiệu quả hơn và lô hàng tiếp theo đáng tin cậy hơn.": "När vi arbetar med en kund tittar vi inte bara på den aktuella beställningen. Vi tittar på hur du gör din nästa beställning mer stabil, din nästa produktionscykel mer effektiv och din nästa leverans mer tillförlitlig.",
    "Khi một vấn đề xảy ra, ANSLIFE không muốn chỉ đóng lại sau một lần sửa chữa. Chúng tôi muốn hiểu đó là lỗi đơn lẻ hay lỗi lặp lại, lỗi đến từ vật liệu, phương pháp sản xuất, phương pháp kiểm tra, đóng gói, logistics hay giao tiếp.": "När ett problem uppstår vill ANSLIFE inte bara stänga ner efter en reparation. Vi vill förstå om det är ett enstaka fel eller ett upprepat fel, om felet kommer från material, produktionsmetoder, inspektionsmetoder, förpackningar, logistik eller kommunikation.",
    "Kho bãi an toàn, quản lý tồn kho và chuẩn bị xuất hàng định kỳ.": "Säkert lager, lagerhantering och förberedelse för periodisk leverans.",
    "Không chỉ trao học bổng, chúng tôi đồng hành cùng hành trình học tập.": "Vi delar inte bara ut stipendier, vi följer med på inlärningsresan.",
    "Không làm theo chiến dịch ngắn hạn, mà xây chương trình có vòng đời rõ ràng.": "Följ inte kortsiktiga kampanjer, utan bygg program med en tydlig livscykel.",
    "Không ngừng nâng cao chất lượng sản phẩm và dịch vụ.": "Ständigt förbättra kvaliteten på produkter och tjänster.",
    "Không phụ thuộc vào một nhà máy": "Inte beroende av en fabrik",
