    "Trách nhiệm này bao gồm chuẩn bị vật liệu, kiểm soát sản xuất, kiểm tra chất lượng, bảo vệ khi đóng gói, chứng từ xuất hàng, phối hợp logistics và phản hồi sau khi hàng đến.": "Detta ansvar inkluderar materialberedning, produktionskontroll, kvalitetskontroll, förpackningsskydd, fraktdokument, logistiksamordning och feedback efter ankomst.",
