    "Buyer có thể liên hệ ANSLIFE để gửi yêu cầu sản phẩm, bản vẽ, mẫu, vật liệu hoặc kế hoạch lưu kho – xuất hàng từ Việt Nam.": "Les acheteurs peuvent contacter ANSLIFE pour envoyer des demandes de produits, des dessins, des échantillons, des matériaux ou des plans de stockage - exporter des marchandises du Vietnam.",
    "Buyer gửi yêu cầu": "L'acheteur envoie la demande",
    "Cá nhân muốn đồng hành các hoạt động cộng đồng": "Personnes souhaitant accompagner des activités communautaires",
