    "Dù sản xuất tại bất kỳ nhà máy nào, mọi hoạt động đều phải tuân theo:": "Quelle que soit la production dans n'importe quelle usine, toutes les activités doivent être conformes:",
    "Duy trì chất lượng ổn định trên toàn hệ thống": "Maintenir une qualité stable dans tout le système",
    "Duy trì kênh phản hồi trực tiếp từ cộng đồng thụ hưởng": "Maintenir un canal de retour d'information direct de la communauté bénéficiaire",
    "DỮ LIỆU": "DONNÉES",
    "Dữ liệu bao gồm:": "Les données comprennent:",
    "Dữ liệu được cập nhật theo thời gian thực, kiểm soát trước khi chia sẻ và phân quyền theo từng tài khoản.": "Les données sont mises à jour en temps réel, contrôlées avant partage et autorisées par chaque compte.",
    "Dữ liệu được luân chuyển theo nguyên tắc:": "Les données circulent selon le principe:",
    "Dữ liệu không chỉ để lưu trữ, mà để:": "Les données ne sont pas uniquement destinées au stockage, mais également à:",
    "Dữ liệu lỗi": "Données d'erreur",
    "Dữ liệu QC": "Données CQ",
    "Dữ liệu QC được ghi nhận trực tiếp tại hiện trường, lưu trữ trên hệ thống và kiểm soát nhiều lớp trước khi sử dụng.": "Les données QC sont enregistrées directement sur les lieux, stockées sur le système et contrôlées dans de nombreuses couches avant utilisation.",
    "Dữ liệu sản xuất": "Données de production",
    "Dữ liệu sản xuất được quản lý tập trung": "Les données de production sont gérées de manière centralisée",
