    "Đối tác sản xuất, chuỗi cung ứng và xuất khẩu tại Việt Nam": "Partenaires de fabrication, de chaîne d'approvisionnement et d'exportation au Vietnam",
    "Đối tác thương mại": "Partenaires commerciaux",
