    "Đối tượng ưu tiên": "Objet prioritaire",
    "Đối với ANSLIFE, dữ liệu không chỉ dùng để báo cáo. Dữ liệu là công cụ làm việc để ra quyết định tốt hơn, kiểm soát chất lượng tốt hơn và quản lý dự án tốt hơn.": "Pour ANSLIFE, les données ne sont pas uniquement destinées au reporting. Les données sont un outil de travail pour une meilleure prise de décision, un meilleur contrôle qualité et une meilleure gestion de projet.",
    "Đối với ANSLIFE, niềm tin không được tạo ra chỉ bằng lời nói. Niềm tin được tạo ra bằng hành động hằng ngày, dữ liệu rõ ràng, trách nhiệm được lặp lại và tinh thần sẵn sàng cải tiến sau mỗi dự án.": "Pour ANSLIFE, la confiance ne se crée pas uniquement par des mots. La confiance se crée grâce à une action quotidienne, des données claires, une responsabilité reproductible et une volonté de s'améliorer à chaque projet.",
    "Đối với chúng tôi, niềm tin dài hạn phải được xây dựng bằng trách nhiệm được lặp lại, dữ liệu minh bạch, cải tiến liên tục và những hành động thực tế trong vận hành hằng ngày.": "Pour nous, la confiance à long terme doit être construite avec une responsabilité répétée, des données transparentes, une amélioration continue et des actions réelles dans les opérations quotidiennes.",
