    "Được đánh giá và kiểm soát định kỳ": "Évalué et contrôlé périodiquement",
    "được hình thành từ nền tảng sản xuất nội thất thực tế tại Việt Nam. Từ một xưởng sản xuất thủ công tại làng nghề Cần Kiệm, Thạch Thất, Hà Nội, ANSLIFE từng bước phát triển năng lực thiết kế, thi công, gia công xuất khẩu, kiểm soát chất lượng,": "a été créée à partir de la base de la production de meubles au Vietnam. Depuis un atelier d'artisanat dans le village artisanal de Can Kiem, Thach That, Hanoi, ANSLIFE a progressivement développé la capacité de conception, de construction, de transformation des exportations, de contrôle de qualité,",
