    "global@anslife.com": "global@ANSLIFE.com",
    "Gửi bản vẽ, yêu cầu sản phẩm, vật liệu hoặc nhu cầu lưu kho để đội ngũ ANSLIFE xem xét và đề xuất giải pháp phù hợp.": "Soumettre les dessins, les exigences du produit, les matériaux ou les besoins de stockage pour que l'équipe ANSLIFE les examine et propose des solutions appropriées.",
