    "Hệ thống dữ liệu": "Système de données",
    "Hệ thống dữ liệu giúp giảm phụ thuộc vào con người, tăng tính minh bạch và hỗ trợ ra quyết định nhanh.": "Les systèmes de données contribuent à réduire la dépendance à l'égard des personnes, à accroître la transparence et à faciliter une prise de décision rapide.",
    "Hệ thống kiểm soát chất lượng": "Système de contrôle qualité",
    "Hệ thống kiểm soát chất lượng (QC)": "Système de contrôle qualité (CQ)",
    "Hệ thống này giúp giảm rủi ro pháp lý, tăng độ tin cậy với đối tác và đảm bảo hoạt động dài hạn.": "Ce système permet de réduire les risques juridiques, d'augmenter la fiabilité avec les partenaires et d'assurer la pérennité des opérations.",
    "Hệ thống này giúp loại bỏ sai lệch thông tin, giảm rủi ro vận hành và đảm bảo tính minh bạch.": "Ce système permet d'éliminer les distorsions d'information, de réduire les risques opérationnels et d'assurer la transparence.",
    "Hệ thống nhà máy": "Système d'usine",
    "Hệ thống QC (tổ trưởng QC, QC nhân sự)": "Système QC (chef d'équipe QC, HR QC)",
    "Hệ thống QC bao gồm:": "Le système CQ comprend:",
    "Hệ thống QC của ANSLIFE hoạt động độc lập với bộ máy sản xuất, nhằm đảm bảo việc kiểm tra được thực hiện khách quan theo tiêu chuẩn đã thống nhất.": "Le système QC d'ANSLIFE fonctionne indépendamment de l'appareil de production, pour garantir que l'inspection est effectuée de manière objective conformément aux normes convenues.",
    "Hệ thống QC độc lập đảm bảo chất lượng đúng tiêu chuẩn quốc tế.": "Un système de contrôle qualité indépendant garantit une qualité conforme aux normes internationales.",
    "Hệ thống QC là lực lượng quan trọng nhất trong vận hành của ANSLIFE.": "Le système QC est la force la plus importante dans les opérations d'ANSLIFE.",
    "Hệ thống R&D:": "Système R&D:",
