    "Hiệu quả chương trình được đánh giá bằng khả năng ứng dụng nghề và tính bền vững của việc làm.": "L'efficacité du programme est évaluée par son applicabilité professionnelle et la durabilité de l'emploi.",
    "Hiệu quả cộng đồng được đo bằng mức độ tác động thực tế và khả năng duy trì kết quả.": "L'efficacité de la communauté se mesure par le niveau d'impact réel et la capacité à pérenniser les résultats.",
    "Hiệu quả đồng hành được đánh giá bằng độ bền vững của chương trình và kết quả thực tế.": "L'efficacité du compagnonnage est évaluée par la durabilité du programme et les résultats réels.",
