    "Kết nối các nguồn lực sản xuất tại nhiều quốc gia": "Connecter les ressources de production dans de nombreux pays",
    "Kết nối học viên với cơ hội việc làm phù hợp": "Mettre les étudiants en contact avec des opportunités d'emploi adaptées",
