    "Kết nối nguyên liệu, sản xuất, QC và hậu cần để giảm rủi ro tiến độ.": "Connectez les matériaux, la production, le contrôle qualité et la logistique pour réduire les risques liés au calendrier.",
    "Kết nối với ANSLIFE": "Connectez-vous à ANSLIFE",
    "Kết quả chương trình được đánh giá theo chu kỳ quý và năm để liên tục nâng chất lượng hoạt động.": "Les résultats du programme sont évalués sur une base trimestrielle et annuelle afin d'améliorer continuellement la qualité des opérations.",
    "Khách hàng": "Clients",
    "Khách hàng (Buyer)": "Client (Acheteur)",
    "Khách hàng truy cập thông tin": "Les clients accèdent aux informations",
    "Khám phá mô hình hoạt động và năng lực của ANSLIFE.": "Explorez le modèle opérationnel et les capacités d'ANSLIFE.",
    "Khảo sát nhu cầu thực địa và xác định nhóm thụ hưởng": "Enquêter sur les besoins sur le terrain et identifier les groupes bénéficiaires",
    "Khi làm việc với một khách hàng, chúng tôi không chỉ nhìn vào đơn hàng hiện tại. Chúng tôi xem xét cách để đơn hàng tiếp theo ổn định hơn, chu kỳ sản xuất tiếp theo hiệu quả hơn và lô hàng tiếp theo đáng tin cậy hơn.": "Lorsque nous travaillons avec un client, nous ne regardons pas seulement la commande en cours. Nous examinons comment rendre votre prochaine commande plus stable, votre prochain cycle de production plus efficace et votre prochaine expédition plus fiable.",
    "Khi một vấn đề xảy ra, ANSLIFE không muốn chỉ đóng lại sau một lần sửa chữa. Chúng tôi muốn hiểu đó là lỗi đơn lẻ hay lỗi lặp lại, lỗi đến từ vật liệu, phương pháp sản xuất, phương pháp kiểm tra, đóng gói, logistics hay giao tiếp.": "Lorsqu'un problème survient, ANSLIFE ne souhaite pas simplement s'arrêter après une seule réparation. Nous voulons comprendre s'il s'agit d'une erreur unique ou d'une erreur répétée, si l'erreur provient des matériaux, des méthodes de production, des méthodes d'inspection, de l'emballage, de la logistique ou de la communication.",
    "Kho bãi an toàn, quản lý tồn kho và chuẩn bị xuất hàng định kỳ.": "Entrepôt sécurisé, gestion des stocks et préparation des expéditions périodiques.",
    "Không chỉ trao học bổng, chúng tôi đồng hành cùng hành trình học tập.": "Non seulement nous attribuons des bourses, mais nous accompagnons le parcours d'apprentissage.",
    "Không làm theo chiến dịch ngắn hạn, mà xây chương trình có vòng đời rõ ràng.": "Ne suivez pas de campagnes à court terme, mais construisez des programmes avec un cycle de vie clair.",
    "Không ngừng nâng cao chất lượng sản phẩm và dịch vụ.": "Améliorer continuellement la qualité des produits et des services.",
