    "Nhân sự tại các nhà máy trong hệ sinh thái": "Ressources humaines dans les usines de l'écosystème",
    "Nhật Bản": "Japon",
    "Nhật Bản, Hoa Kỳ, EU và buyer quốc tế": "Acheteurs japonais, américains, européens et internationaux",
    "Nhóm chương trình đào tạo": "Groupe programme de formation",
    "Nhóm đối tượng tại khu vực ưu tiên cộng đồng": "Groupes cibles dans les domaines prioritaires de la communauté",
    "Niềm tin dài hạn quan trọng hơn lợi nhuận ngắn hạn": "La confiance à long terme est plus importante que les profits à court terme",
    "OEM / ODM": "OEM / ODM",
    "Ở giai đoạn này, ANSLIFE tham gia với vai trò gia công cho các nhà xuất khẩu tại Việt Nam, phục vụ các đơn hàng xuất khẩu sang thị trường Hoa Kỳ.": "À ce stade, ANSLIFE participe au rôle d'externalisation pour les exportateurs au Vietnam, en servant les commandes d'exportation vers le marché américain.",
    "Partner Participation Growth": "Croissance de la participation des partenaires",
