    "Phát hiện và kiểm soát lỗi từ sớm": "Détecter et contrôler les erreurs à un stade précoce",
    "Phát triển bền vững": "Développement durable",
    "Phát triển chuỗi cung ứng": "Développement de la chaîne d'approvisionnement",
