    "Sứ mệnh": "Missions",
    "Sứ mệnh của ANSLIFE là xây dựng một hệ thống sản xuất minh bạch, có thể kiểm soát và có khả năng mở rộng toàn cầu, giúp kết nối hiệu quả giữa khách hàng quốc tế và mạng lưới sản xuất.": "La mission d'ANSLIFE est de construire un système de production transparent, contrôlable et évolutif à l'échelle mondiale qui connecte efficacement les clients internationaux et les réseaux de production.",
    "Tại ANSLIFE, con người không vận hành độc lập. Con người vận hành trong hệ thống.": "Chez ANSLIFE, les gens ne fonctionnent pas de manière indépendante. Les gens opèrent au sein du système.",
