    "Trách nhiệm": "Responsabilité",
    "Trách nhiệm này bao gồm chuẩn bị vật liệu, kiểm soát sản xuất, kiểm tra chất lượng, bảo vệ khi đóng gói, chứng từ xuất hàng, phối hợp logistics và phản hồi sau khi hàng đến.": "Cette responsabilité comprend la préparation du matériel, le contrôle de la production, le contrôle de la qualité, la protection de l'emballage, les documents d'expédition, la coordination logistique et le retour d'information après l'arrivée.",
    "Trách nhiệm vượt ra ngoài việc sản xuất": "Les responsabilités vont au-delà de la production",
