    "Vận hành theo tiêu chuẩn quốc tế": "Fonctionne selon les normes internationales",
    "Vật liệu, mẫu sơn, bảng màu, veneer, plywood, foam, vải, phụ kiện và vật liệu đóng gói được kiểm soát theo tiêu chuẩn của từng buyer và từng thị trường.": "Les matériaux, échantillons de peinture, palettes de couleurs, placages, contreplaqués, mousses, tissus, accessoires et matériaux d'emballage sont contrôlés selon les normes de chaque acheteur et de chaque marché.",
    "Về ANSLIFE": "À propos d'ANSLIFE",
