    "DỮ LIỆU": "ДАННЫЕ",
    "Dữ liệu bao gồm:": "Данные включают в себя:",
    "Dữ liệu được cập nhật theo thời gian thực, kiểm soát trước khi chia sẻ và phân quyền theo từng tài khoản.": "Данные обновляются в режиме реального времени, контролируются перед отправкой и авторизуются каждой учетной записью.",
    "Dữ liệu được luân chuyển theo nguyên tắc:": "Данные распространяются по принципу:",
    "Dữ liệu không chỉ để lưu trữ, mà để:": "Данные предназначены не только для хранения, но и для:",
