    "Đối tác sản xuất, chuỗi cung ứng và xuất khẩu tại Việt Nam": "Партнеры по производству, цепочке поставок и экспорту во Вьетнаме",
    "Đối tác thương mại": "Торговые партнеры",
    "Đối tượng có thể tham gia": "Субъекты могут участвовать",
    "Đối tượng ưu tiên": "Приоритетный объект",
    "Đối với ANSLIFE, dữ liệu không chỉ dùng để báo cáo. Dữ liệu là công cụ làm việc để ra quyết định tốt hơn, kiểm soát chất lượng tốt hơn và quản lý dự án tốt hơn.": "Для ANSLIFE данные предназначены не только для отчетов. Данные — это рабочий инструмент для лучшего принятия решений, лучшего контроля качества и лучшего управления проектами.",
    "Đối với ANSLIFE, niềm tin không được tạo ra chỉ bằng lời nói. Niềm tin được tạo ra bằng hành động hằng ngày, dữ liệu rõ ràng, trách nhiệm được lặp lại và tinh thần sẵn sàng cải tiến sau mỗi dự án.": "Для ANSLIFE доверие создается не только словами. Доверие создается ежедневными действиями, четкими данными, повторяемой подотчетностью и готовностью совершенствоваться с каждым проектом.",
    "Đối với chúng tôi, niềm tin dài hạn phải được xây dựng bằng trách nhiệm được lặp lại, dữ liệu minh bạch, cải tiến liên tục và những hành động thực tế trong vận hành hằng ngày.": "Для нас долгосрочное доверие должно строиться на основе повторяющейся отчетности, прозрачных данных, постоянного совершенствования и реальных действий в повседневной деятельности.",
