    "Được đánh giá và kiểm soát định kỳ": "Периодически оценивается и контролируется",
    "được hình thành từ nền tảng sản xuất nội thất thực tế tại Việt Nam. Từ một xưởng sản xuất thủ công tại làng nghề Cần Kiệm, Thạch Thất, Hà Nội, ANSLIFE từng bước phát triển năng lực thiết kế, thi công, gia công xuất khẩu, kiểm soát chất lượng,": "была основана на базе настоящего мебельного производства во Вьетнаме. Из ремесленной мастерской в ремесленной деревне Кан Кием, Тхат Тхат, Ханой, ANSLIFE постепенно развила возможности проектирования, строительства, экспортной обработки, контроля качества,",
