    "Hệ thống QC (tổ trưởng QC, QC nhân sự)": "Система контроля качества (руководитель группы контроля качества, отдел контроля качества кадров)",
    "Hệ thống QC bao gồm:": "Система контроля качества включает в себя:",
    "Hệ thống QC của ANSLIFE hoạt động độc lập với bộ máy sản xuất, nhằm đảm bảo việc kiểm tra được thực hiện khách quan theo tiêu chuẩn đã thống nhất.": "Система контроля качества ANSLIFE работает независимо от производственного оборудования, обеспечивая объективность проверки в соответствии с согласованными стандартами.",
    "Hệ thống QC độc lập đảm bảo chất lượng đúng tiêu chuẩn quốc tế.": "Независимая система контроля качества обеспечивает качество в соответствии с международными стандартами.",
    "Hệ thống QC là lực lượng quan trọng nhất trong vận hành của ANSLIFE.": "Система контроля качества является наиболее важной силой в деятельности ANSLIFE.",
