    "Hiệu quả cộng đồng được đo bằng mức độ tác động thực tế và khả năng duy trì kết quả.": "Эффективность сообщества измеряется уровнем фактического воздействия и способностью поддерживать результаты.",
    "Hiệu quả đồng hành được đánh giá bằng độ bền vững của chương trình và kết quả thực tế.": "Эффективность дружеского общения оценивается устойчивостью программы и фактическими результатами.",
