    "Mạng lưới nhà máy & đối tác rộng khắp": "Обширная сеть фабрик и партнеров",
    "Mạng lưới nhà máy do ANSLIFE điều phối đáp ứng nhiều yêu cầu và tiêu chuẩn.": "Заводская сеть, координируемая ANSLIFE, отвечает многим требованиям и стандартам.",
