    "Mở rộng vai trò vận hành và quản lý dự án xuất khẩu": "Расширение функций управления экспортными проектами и операций",
    "Mở rộng xuất khẩu và ra mắt thương hiệu ANSLIFE": "Расширение экспорта и запуск бренда ANSLIFE",
    "Mục tiêu của chúng tôi không chỉ là xuất hàng. Mục tiêu của chúng tôi là giúp khách hàng nhận được sản phẩm ổn định, có thể truy xuất và đáng tin cậy.": "Наша цель — не просто доставлять товары. Наша цель — помочь клиентам получать стабильную, отслеживаемую и надежную продукцию.",
    "Mục tiêu của quỹ": "Цель фонда",
