    "Tổng quan ANSLIFE": "Обзор ANSLIFE",
    "Tổng quan công ty": "Обзор компании",
    "Trách nhiệm": "Ответственность",
    "Trách nhiệm này bao gồm chuẩn bị vật liệu, kiểm soát sản xuất, kiểm tra chất lượng, bảo vệ khi đóng gói, chứng từ xuất hàng, phối hợp logistics và phản hồi sau khi hàng đến.": "Эта ответственность включает в себя подготовку материалов, производственный контроль, контроль качества, защиту упаковки, отгрузочные документы, координацию логистики и обратную связь после прибытия.",
    "Trách nhiệm vượt ra ngoài việc sản xuất": "Обязанности выходят за рамки производства",
    "Training Completion Rate": "Процент завершения обучения",
    "TRANG WEB ANSLIFE V1": "ВЕБ-САЙТ ANSLIFE V1",
    "Triết lý": "Философия",
    "Triết lý ANSLIFE": "Философия ANSLIFE",
    "TRIẾT LÝ KINH DOANH": "БИЗНЕС-ФИЛОСОФИЯ",
    "Triết lý phát triển": "Философия разработки",
    "Triết lý và cam kết phát triển": "Философия и приверженность развитию",
    "trong các giai đoạn sau.": "на следующих этапах.",
    "Trong dài hạn, ANSLIFE hướng tới việc xây dựng một mạng lưới sản xuất toàn cầu có tính ổn định cao, linh hoạt về công suất và minh bạch trong toàn bộ quá trình vận hành.": "В долгосрочной перспективе ANSLIFE стремится построить глобальную производственную сеть, которая будет очень стабильной, гибкой по мощности и прозрачной на протяжении всего рабочего процесса.",
    "Trong giai đoạn này, công ty chuyển trụ sở chính về Tầng 5, Số 12 Khuất Duy Tiến, Phường Thanh Xuân Trung, Quận Thanh Xuân, Thành phố Hà Nội, Việt Nam.": "В этот период компания переместила свою штаб-квартиру на 5-й этаж, № 12 Хуат Дуй Тьен, район Тхань Суан Чунг, район Тхань Суан, город Ханой, Вьетнам.",
    "Trong năm này, ANSLIFE thành lập phòng kiểm soát chất lượng để thực hiện nhiệm vụ kiểm tra, theo dõi và kiểm soát chất lượng cho các đơn hàng.": "В этом году ANSLIFE создала отдел контроля качества для выполнения задач по проверке, мониторингу и контролю качества заказов.",
    "Trong năm này, thương hiệu ANSLIFE chính thức được ra mắt, đánh dấu bước chuyển từ hoạt động gia công đơn lẻ sang định hướng xây dựng hệ thống sản xuất và xuất khẩu nội thất.": "В этом году был официально запущен бренд ANSLIFE, что ознаменовало переход от единичной деятельности по переработке к ориентации на построение системы производства и экспорта мебели.",
    "Trụ sở": "Штаб-квартира",
