    "Vận hành theo hệ sinh thái sản xuất được kiểm soát tập trung.": "Работает в рамках централизованно контролируемой производственной экосистемы.",
    "Vận hành theo tiêu chuẩn quốc tế": "Работает в соответствии с международными стандартами.",
    "Vật liệu, mẫu sơn, bảng màu, veneer, plywood, foam, vải, phụ kiện và vật liệu đóng gói được kiểm soát theo tiêu chuẩn của từng buyer và từng thị trường.": "Материалы, образцы красок, цветовые палитры, шпон, фанера, пенопласт, ткань, фурнитура и упаковочные материалы контролируются в соответствии со стандартами каждого покупателя и каждого рынка.",
