    "Cùng hành động có hệ thống để tạo tác động dài hạn.": "Tomar medidas sistemáticas en conjunto para crear un impacto a largo plazo.",
    "Danh mục chương trình cộng đồng": "Directorio de programas comunitarios",
    "Data Admin": "Administrador de datos",
    "Data Controller": "Responsable del tratamiento de datos",
    "Data Controller / Data Admin": "Controlador de datos / Administrador de datos",
