    "Dịch vụ chính": "Servicio principal",
    "Doanh nghiệp muốn tài trợ chương trình giáo dục": "Las empresas quieren patrocinar programas educativos",
    "Dù sản xuất tại bất kỳ nhà máy nào, mọi hoạt động đều phải tuân theo:": "Independientemente de la producción en cualquier fábrica, todas las actividades deben cumplir con:",
    "Duy trì chất lượng ổn định trên toàn hệ thống": "Mantener la calidad estable en todo el sistema.",
    "Duy trì kênh phản hồi trực tiếp từ cộng đồng thụ hưởng": "Mantener un canal de retroalimentación directa de la comunidad beneficiaria.",
    "DỮ LIỆU": "DATOS",
    "Dữ liệu bao gồm:": "Los datos incluyen:",
    "Dữ liệu được cập nhật theo thời gian thực, kiểm soát trước khi chia sẻ và phân quyền theo từng tài khoản.": "Los datos se actualizan en tiempo real, se controlan antes de compartirlos y son autorizados por cada cuenta.",
    "Dữ liệu được luân chuyển theo nguyên tắc:": "Los datos se distribuyen según el principio:",
    "Dữ liệu không chỉ để lưu trữ, mà để:": "Los datos no son sólo para almacenamiento, sino para:",
    "Dữ liệu lỗi": "Datos de error",
    "Dữ liệu QC": "Datos de control de calidad",
    "Dữ liệu QC được ghi nhận trực tiếp tại hiện trường, lưu trữ trên hệ thống và kiểm soát nhiều lớp trước khi sử dụng.": "Los datos de control de calidad se registran directamente en el lugar, se almacenan en el sistema y se controlan en muchas capas antes de su uso.",
    "Dữ liệu sản xuất": "Datos de producción",
    "Dữ liệu sản xuất được quản lý tập trung": "Los datos de producción se gestionan de forma centralizada.",
    "Dữ liệu tiến độ": "Datos de progreso",
    "Đa thị trường": "Multimercado",
    "Đảm bảo chất lượng và tiến độ ở quy mô lớn": "Garantizar la calidad y el progreso a gran escala",
    "Đảm bảo dữ liệu cung cấp cho sale và khách hàng là dữ liệu đã được kiểm soát": "Garantizar que los datos proporcionados a ventas y clientes sean datos controlados.",
    "Đảm bảo quyền lợi của các bên tham gia": "Garantizar los derechos de las partes participantes",
    "Đảm bảo sản phẩm đạt yêu cầu trước khi xuất hàng": "Asegúrese de que los productos cumplan con los requisitos antes del envío",
    "Đánh giá đầu ra theo chỉ số đã cam kết": "Evaluar los resultados según los indicadores comprometidos",
    "Đánh giá năng lực theo tiêu chí thống nhất": "Evaluar capacidad según criterios unificados",
    "Đánh giá tác động sau chương trình": "Evaluar el impacto después del programa",
    "Đánh giá theo bộ tiêu chí đã công bố": "Evaluado según el conjunto de criterios publicados",
    "Đào tạo kỹ năng mềm và tác phong nghề nghiệp": "Capacitación en habilidades blandas y comportamiento profesional.",
    "Đào tạo kỹ năng nghề và an toàn làm việc": "Formación profesional y seguridad en el trabajo",
    "Đào tạo kỹ năng nghề, phát triển đội ngũ quản lý và nâng cao năng lực sản xuất.": "Formación profesional, desarrollo de equipos directivos y mejora de la capacidad productiva.",
    "Đào tạo kỹ năng số và quản trị dữ liệu cơ bản": "Capacitación en habilidades digitales básicas y gestión de datos",
    "Đào tạo thực tế trong sản xuất": "Formación práctica en producción.",
    "Đầu tư cho con người là nền tảng của phát triển dài hạn.": "Invertir en las personas es la base del desarrollo a largo plazo.",
    "Đầu tư con người": "Invertir en las personas",
    "Đầu tư vào con người để tạo năng lực vận hành bền vững cho cộng đồng và doanh nghiệp.": "Invertir en personas para crear capacidad operativa sostenible para comunidades y empresas.",
    "Đầu tư vào đào tạo, môi trường làm việc và cơ hội phát triển cho đội ngũ nhân sự.": "Invertir en capacitación, ambiente de trabajo y oportunidades de desarrollo para el personal.",
    "Đây là bước phát triển quan trọng trong việc tách hoạt động kiểm soát chất lượng khỏi bộ máy sản xuất, giúp ANSLIFE nâng cao tính khách quan, khả năng truy xuất và mức độ kiểm soát trong các đơn hàng xuất khẩu.": "Este es un avance importante al separar las actividades de control de calidad del aparato de producción, ayudando a ANSLIFE a mejorar la objetividad, la trazabilidad y el nivel de control en los pedidos de exportación.",
    "Đây là giai đoạn ANSLIFE mở rộng từ sản xuất nội thất sang thiết kế, tư vấn và triển khai không gian nội thất hoàn chỉnh.": "Este es el período en el que ANSLIFE pasó de la producción de muebles al diseño, consultoría e implementación de espacios interiores completos.",
    "Đây là lõi vận hành của hệ thống ANSLIFE.": "Este es el núcleo operativo del sistema ANSLIFE.",
    "Đây là lý do ANSLIFE chuẩn hóa việc kiểm soát vật liệu, chuẩn bị hàng trắng, kiểm tra mộng liên kết, kiểm soát hoàn thiện sơn, bảo vệ đóng gói, bảng tiến độ dự án và hồ sơ lỗi xuyên đơn hàng.": "Es por esto que ANSLIFE estandariza el control de materiales, preparación de electrodomésticos, inspección de juntas, control de acabado de pintura, protección de empaques, hojas de cronograma de proyectos y registros de defectos entre pedidos.",
    "Đây là lý do ANSLIFE tiếp tục đầu tư vào kiểm soát vật liệu, kế hoạch sản xuất, kiểm tra chất lượng, tiêu chuẩn đóng gói, theo dõi dự án và hồ sơ cải tiến.": "Es por esto que ANSLIFE continúa invirtiendo en control de materiales, planificación de producción, inspección de calidad, estándares de empaque, seguimiento de proyectos y registros de mejora.",
    "Đây là một cột mốc quan trọng, vì thị trường Nhật Bản có yêu cầu cao về chất lượng, độ ổn định, tiêu chuẩn đóng gói, kiểm soát chi tiết và khả năng duy trì tiêu chuẩn sản phẩm trong dài hạn.": "Este es un hito importante, ya que el mercado japonés tiene altos requisitos de calidad, estabilidad, estándares de empaque, control detallado y la capacidad de mantener los estándares del producto a largo plazo.",
    "Đây là nền tảng quan trọng để ANSLIFE phát triển hệ thống": "Esta es una base importante para que ANSLIFE desarrolle el sistema.",
    "Đây là trung tâm kiểm soát toàn bộ hoạt động của ANSLIFE.": "Este es el centro que controla todas las operaciones de ANSLIFE.",
    "Đề xuất điều chỉnh về kết cấu, vật liệu, màu sơn và khả năng sản xuất": "Proponer ajustes a estructura, materiales, colores de pintura y capacidades de fabricación.",
    "Đến giai đoạn này, ANSLIFE sở hữu năng lực sản xuất thông qua hệ thống nhà máy vệ tinh đa dạng, mạng lưới cung cấp nguyên liệu và kinh nghiệm vận hành các đơn hàng xuất khẩu.": "En esta etapa, ANSLIFE posee capacidad de producción a través de un diverso sistema de fábricas satélites, red de suministro de materias primas y experiencia en la operación de pedidos de exportación.",
    "Địa chỉ": "Dirección",
