    "Đối tượng có thể tham gia": "Los sujetos pueden participar",
    "Đối tượng ưu tiên": "Objeto prioritario",
    "Đối với ANSLIFE, dữ liệu không chỉ dùng để báo cáo. Dữ liệu là công cụ làm việc để ra quyết định tốt hơn, kiểm soát chất lượng tốt hơn và quản lý dự án tốt hơn.": "Para ANSLIFE los datos no son sólo para reportar. Los datos son una herramienta de trabajo para una mejor toma de decisiones, un mejor control de calidad y una mejor gestión de proyectos.",
    "Đối với ANSLIFE, niềm tin không được tạo ra chỉ bằng lời nói. Niềm tin được tạo ra bằng hành động hằng ngày, dữ liệu rõ ràng, trách nhiệm được lặp lại và tinh thần sẵn sàng cải tiến sau mỗi dự án.": "Para ANSLIFE la confianza no se crea solo con palabras. La confianza se crea con acciones diarias, datos claros, responsabilidad repetible y voluntad de mejorar con cada proyecto.",
    "Đối với chúng tôi, niềm tin dài hạn phải được xây dựng bằng trách nhiệm được lặp lại, dữ liệu minh bạch, cải tiến liên tục và những hành động thực tế trong vận hành hằng ngày.": "Para nosotros, la confianza a largo plazo debe construirse con responsabilidad repetida, datos transparentes, mejora continua y acciones reales en las operaciones diarias.",
    "Đối với hệ sinh thái": "Por el ecosistema",
