    "Được đánh giá và kiểm soát định kỳ": "Evaluado y controlado periódicamente",
    "được hình thành từ nền tảng sản xuất nội thất thực tế tại Việt Nam. Từ một xưởng sản xuất thủ công tại làng nghề Cần Kiệm, Thạch Thất, Hà Nội, ANSLIFE từng bước phát triển năng lực thiết kế, thi công, gia công xuất khẩu, kiểm soát chất lượng,": "se formó a partir de la base de la producción actual de muebles en Vietnam. Desde un taller de artesanía en el pueblo artesanal de Can Kiem, Thach That, Hanoi, ANSLIFE ha desarrollado gradualmente la capacidad de diseño, construcción, procesamiento de exportación, control de calidad,",
