    "Hệ thống nhà máy": "Sistema de fábrica",
    "Hệ thống QC (tổ trưởng QC, QC nhân sự)": "Sistema de control de calidad (líder del equipo de control de calidad, control de calidad de recursos humanos)",
    "Hệ thống QC bao gồm:": "El sistema de control de calidad incluye:",
    "Hệ thống QC của ANSLIFE hoạt động độc lập với bộ máy sản xuất, nhằm đảm bảo việc kiểm tra được thực hiện khách quan theo tiêu chuẩn đã thống nhất.": "El sistema de control de calidad de ANSLIFE funciona independientemente del aparato de producción, para garantizar que la inspección se realice objetivamente de acuerdo con los estándares acordados.",
    "Hệ thống QC độc lập đảm bảo chất lượng đúng tiêu chuẩn quốc tế.": "El sistema de control de calidad independiente garantiza la calidad de acuerdo con los estándares internacionales.",
    "Hệ thống QC là lực lượng quan trọng nhất trong vận hành của ANSLIFE.": "El sistema de control de calidad es la fuerza más importante en las operaciones de ANSLIFE.",
