    "Nhân sự QC tại các nhà máy": "Personal de control de calidad en fábricas",
    "Nhân sự tại các nhà máy trong hệ sinh thái": "Recursos humanos en las fábricas del ecosistema.",
    "Nhật Bản": "Japón",
    "Nhật Bản, Hoa Kỳ, EU và buyer quốc tế": "Japón, EE.UU., UE y compradores internacionales",
    "Nhóm chương trình đào tạo": "Grupo de programas de entrenamiento",
    "Nhóm đối tượng tại khu vực ưu tiên cộng đồng": "Grupos objetivo en áreas prioritarias de la comunidad",
    "Niềm tin dài hạn quan trọng hơn lợi nhuận ngắn hạn": "La confianza a largo plazo es más importante que las ganancias a corto plazo",
    "OEM / ODM": "OEM / ODM",
    "Ở giai đoạn này, ANSLIFE tham gia với vai trò gia công cho các nhà xuất khẩu tại Việt Nam, phục vụ các đơn hàng xuất khẩu sang thị trường Hoa Kỳ.": "En esta etapa, ANSLIFE participa en el rol de outsourcing para exportadores en Vietnam, atendiendo pedidos de exportación al mercado estadounidense.",
    "Partner Participation Growth": "Crecimiento de la participación de los socios",
    "Phạm vi tác động": "Rango de impacto",
    "Phát hiện và kiểm soát lỗi từ sớm": "Detectar y controlar errores tempranamente",
