    "Phát triển doanh nghiệp gắn liền với trách nhiệm đối với con người, cộng đồng và sự phát triển bền vững.": "El desarrollo empresarial está asociado a la responsabilidad hacia las personas, la comunidad y el desarrollo sostenible.",
    "Phát triển ngành sản xuất": "Desarrollando la industria manufacturera",
    "Phát triển nguồn nhân lực": "Desarrollo de recursos humanos",
