    "Chất lượng & Tiêu chuẩn": "质量与标准",
    "Chất lượng được kiểm soát bằng hệ thống, không phụ thuộc vào vị trí địa lý": "质量由系统控制，无论地理位置如何",
    "Chất lượng không được đảm bảo bằng lời nói, mà bằng hệ thống kiểm soát xuyên suốt.": "质量不是靠言语来保证的，而是靠彻底的控制体系来保证的。",
    "Chất lượng không được đảm bảo bằng lời nói. Chất lượng được đảm bảo bằng hệ thống kiểm soát.": "质量无法得到口头保证。质量由控制系统保证。",
    "Châu Âu": "欧洲",
    "Checklist kiểm hàng": "检查货物清单",
    "Chia sẻ kinh nghiệm, quy trình và tiêu chuẩn nhằm nâng cao năng lực của chuỗi cung ứng.": "分享经验、流程和标准，以提高供应链能力。",
    "Chia sẻ theo đúng phạm vi": "在正确的范围内分享",
    "cho buyer quốc tế.": "面向国际买家。",
    "Chọn nhóm vật liệu, sau đó vào từng mục con để xem chi tiết.": "选择一个材料组，然后转到每个子部分查看详细信息。",
    "Chu kỳ đánh giá và cải tiến": "评估和改进周期",
    "Chuẩn bị vật liệu & phát triển mẫu": "材料准备和样品开发",
    "Chuẩn hóa quy trình và hệ thống kiểm soát chất lượng": "标准化流程和质量控制系统",
    "Chuẩn hóa và phân phối dữ liệu": "标准化和分布数据",
    "Chúng tôi hướng đến sự phát triển bền vững thông qua việc đầu tư vào con người, nâng cao năng lực sản xuất, hỗ trợ cộng đồng và xây dựng chuỗi cung ứng có trách nhiệm.": "我们的目标是通过对人才的投资、提高生产能力、支持社区和建立负责任的供应链来实现可持续发展。",
    "Chúng tôi hướng tới đội ngũ:": "我们的团队目标是：",
    "Chúng tôi hướng tới:": "我们的目标是：",
    "Chúng tôi không chỉ bán sản phẩm, mà cung cấp giải pháp sản xuất phù hợp với từng thị trường.": "我们不仅销售产品，还提供适合每个市场的生产解决方案。",
    "Chúng tôi không chỉ xây dựng năng lực sản xuất tại Việt Nam, mà từng bước mở rộng hệ sinh thái sang các khu vực khác, nơi các nhà máy được tổ chức và vận hành theo cùng một tiêu chuẩn, cùng một hệ thống kiểm soát và cùng một phương thức quản lý dữ liệu.": "我们不仅在越南建立生产能力，还逐步将生态系统扩展到其他地区，这些地区的工厂按照相同的标准、相同的控制系统和相同的数据管理方法组织和运营。",
    "Chúng tôi không tách rời con người khỏi hệ thống.": "我们不会将人与系统分开。",
    "Chúng tôi quản lý công việc không chỉ bằng trao đổi miệng, mà còn thông qua thư mục dự án, bảng tiến độ, báo cáo kiểm tra, hình ảnh, hồ sơ giao hàng và nhật ký lỗi.": "我们不仅通过口头方式管理工作，还通过项目文件夹、进度表、检查报告、照片、交付记录和错误日志来管理工作。",
    "Chúng tôi sẽ tiếp tục cải thiện hệ thống sản xuất, kiểm soát chuỗi cung ứng, quản lý chất lượng, theo dõi dự án và giao tiếp với khách hàng.": "我们将继续改进我们的生产体系​​、供应链控制、质量管理、项目跟踪和客户沟通。",
    "Chúng tôi tin rằng một công ty tốt không phải là công ty không có vấn đề. Một công ty tốt là công ty có thể học từ vấn đề và trở nên đáng tin cậy hơn theo thời gian.": "我们相信，一家好的公司并不是没有问题的公司。一家好的公司能够从问题中吸取教训，并随着时间的推移变得更加值得信赖。",
    "Chúng tôi tin rằng sự cố ngoài dự kiến có thể xảy ra ở bất kỳ công đoạn nào trong sản xuất hoặc vận chuyển. Vì vậy, ANSLIFE xây dựng hệ thống dự phòng và kế hoạch bảo vệ để hấp thụ rủi ro và bảo vệ dự án.": "我们相信，在生产或运输的任何阶段都可能发生意外事件。因此，ANSLIFE建立了备份系统和保护计划来吸收风险并保护项目。",
    "Chúng tôi vận hành một hệ thống gồm nhà máy do ANSLIFE điều phối, mạng lưới nhà máy vệ tinh, chuỗi cung ứng vật liệu liên tục, hệ thống QC độc lập, kho lưu trữ tại Việt Nam và cơ chế xuất hàng định kỳ.": "我们运营的系统包括由 ANSLIFE 协调的工厂、卫星工厂网络、连续材料供应链、独立的 QC 系统、越南仓储和定期发货机制。",
    "Chúng tôi vận hành theo mô hình hệ sinh thái sản xuất được kiểm soát tập trung.": "我们在集中控制的制造生态系统模型下运营。",
    "Chúng tôi xây dựng một hệ sinh thái sản xuất có thể mở rộng.": "我们构建了一个可扩展的制造生态系统。",
    "Chuỗi cung ứng ổn định & linh hoạt": "稳定灵活的供应链",
    "chuỗi cung ứng vật liệu": "材料供应链",
    "Chuỗi khép kín": "闭链",
    "Chuyển trụ sở chính về Thành phố Hồ Chí Minh và mở rộng hệ thống vệ tinh": "将总部迁至胡志明市并扩大卫星系统",
    "Chương trình chào đón nhiều nhóm đối tác với vai trò phù hợp năng lực đóng góp.": "该计划欢迎许多具有适当作用和贡献能力的合作伙伴群体。",
    "Chương trình được thiết kế để hình thành lực lượng lao động có kỹ năng và kỷ luật vận hành.": "该计划旨在培养一支技术精湛、纪律严明的员工队伍。",
    "Chương trình được triển khai cùng trường nghề, đối tác chuyên môn và đội ngũ vận hành nội bộ.": "该计划由职业学校、专业合作伙伴和内部运营团队共同实施。",
    "Chương trình học bổng": "奖学金计划",
    "Chương trình học bổng ANSLIFE tập trung hỗ trợ học sinh, sinh viên có nỗ lực học tập tốt, ưu tiên nhóm có hoàn cảnh khó khăn và tiềm năng phát triển lâu dài.": "ANSLIFE 奖学金计划侧重于支持学业成绩良好的学生，优先考虑处境困难且具有长期发展潜力的群体。",
    "Chương trình học bổng được đánh giá bằng chỉ số đầu ra và mức độ bền vững của tác động.": "奖学金计划通过产出指标和影响的可持续性进行评估。",
    "Chương trình hướng tới trao cơ hội học tập bền vững thay vì hỗ trợ ngắn hạn một lần.": "该计划旨在提供可持续的学习机会，而不是一次性的短期支持。",
    "Chương trình ưu tiên nhóm học viên cần hỗ trợ để duy trì và phát triển việc học.": "该计划优先考虑需要支持来维持和发展学习的学生群体。",
