    "Đối với ANSLIFE, dữ liệu không chỉ dùng để báo cáo. Dữ liệu là công cụ làm việc để ra quyết định tốt hơn, kiểm soát chất lượng tốt hơn và quản lý dự án tốt hơn.": "对于 ANSLIFE 来说，数据不仅仅用于报告。数据是更好的决策、更好的质量控制和更好的项目管理的工作工具。",
    "Đối với ANSLIFE, niềm tin không được tạo ra chỉ bằng lời nói. Niềm tin được tạo ra bằng hành động hằng ngày, dữ liệu rõ ràng, trách nhiệm được lặp lại và tinh thần sẵn sàng cải tiến sau mỗi dự án.": "对于 ANSLIFE 来说，信任不仅仅是通过言语建立的。信任是通过日常行动、清晰的数据、可重复的责任以及改进每个项目的意愿来建立的。",
    "Đối với chúng tôi, niềm tin dài hạn phải được xây dựng bằng trách nhiệm được lặp lại, dữ liệu minh bạch, cải tiến liên tục và những hành động thực tế trong vận hành hằng ngày.": "对我们来说，长期信任必须通过重复问责、透明数据、持续改进和日常运营中的实际行动来建立。",
