    "Khảo sát nhu cầu thực địa và xác định nhóm thụ hưởng": "调查现场需求并确定受益群体",
    "Khi làm việc với một khách hàng, chúng tôi không chỉ nhìn vào đơn hàng hiện tại. Chúng tôi xem xét cách để đơn hàng tiếp theo ổn định hơn, chu kỳ sản xuất tiếp theo hiệu quả hơn và lô hàng tiếp theo đáng tin cậy hơn.": "与客户合作时，我们不仅仅查看当前订单。我们着眼于如何使您的下一个订单更加稳定，您的下一个生产周期更加高效，以及您的下一个发货更加可靠。",
    "Khi một vấn đề xảy ra, ANSLIFE không muốn chỉ đóng lại sau một lần sửa chữa. Chúng tôi muốn hiểu đó là lỗi đơn lẻ hay lỗi lặp lại, lỗi đến từ vật liệu, phương pháp sản xuất, phương pháp kiểm tra, đóng gói, logistics hay giao tiếp.": "当出现问题时，ANSLIFE 不希望在一次修复后简单地关闭。我们想要了解是单一错误还是重复错误，错误是否来自材料、生产方法、检验方法、包装、物流或沟通。",
    "Kho bãi an toàn, quản lý tồn kho và chuẩn bị xuất hàng định kỳ.": "安全仓库、库存管理和定期装运准备。",
    "Không chỉ trao học bổng, chúng tôi đồng hành cùng hành trình học tập.": "我们不仅提供奖学金，我们还陪伴您的学习之旅。",
    "Không làm theo chiến dịch ngắn hạn, mà xây chương trình có vòng đời rõ ràng.": "不要遵循短期活动，而要制定具有明确生命周期的计划。",
