    "Mẫu sản phẩm, cấu kiện, màu sắc, vật liệu và bề mặt hoàn thiện được lưu giữ làm tiêu chuẩn đối chiếu trong quá trình sản xuất và kiểm hàng.": "产品样品、成分、颜色、材料和表面光洁度在生产和检验过程中作为参考标准。",
