    "Quỹ được thiết kế với mục tiêu rõ ràng, đo lường được và có tính liên tục qua từng năm.": "该基金的设计年复一年都有明确、可衡量和持续的目标。",
    "Quỹ được xây theo lộ trình dài hạn, gắn với chiến lược phát triển cộng đồng của ANSLIFE.": "该基金是根据长期路线图建立的，与 ANSLIFE 的社区发展战略相关。",
